// One-off (but safe-to-repeat) seed: populates backlog-tracker's Firestore
// with the REAL Personalisation Hub FAQ / Help Center content, exported
// from Freshdesk Solutions (personalisationhub.freshdesk.com/a/solutions)
// via the Google Drive folder "Personalisation Hub / Freshdesk FAQs -
// June 2026" — 9 categories, 108 articles, imported verbatim. Article
// bodies no longer carry a trailing "Imported from Freshdesk Solutions
// (Article ID ..., last updated ...)" provenance line — it was stripped
// from every seeded body and from the live faqArticles docs, since it's
// internal import metadata, not something a reader of the public FAQ /
// user guide should see. Draft/Published status is preserved exactly as
// it was in Freshdesk, so this data doubles as a real test of the
// draft-vs-published flow (10 draft articles start hidden from the public
// site until published from FAQ Center, same as any other article).
//
// Replaces the earlier hand-written placeholder categories/articles this
// script used to seed — this is real content now, not a placeholder to
// swap out later. Slug/keywords/summary are derived mechanically from the
// original export by scripts used once during that import (not part of
// this repo); the body text itself is untouched Freshdesk copy.
//
// Same pattern as migrate-artifact-data.js: deterministic doc ids (the
// category slug, or the real Freshdesk Article ID for articles) +
// Firestore's create() (insert-only, fails if the doc already exists), so
// this can never clobber a later edit made from FAQ Center (a rewritten
// body, a status flip, a re-categorisation) by silently reapplying the
// original imported value on top of it.

const { initializeApp, applicationDefault } = require("firebase-admin/app");
const { getFirestore, Timestamp } = require("firebase-admin/firestore");

initializeApp({ credential: applicationDefault() });
const db = getFirestore();
const now = Timestamp.now();

const categories = [
  { id: "faq-cat-queue-management", name: "Queue Management", icon: "queue", description: "Virtual queueing set-up, staff tools, and managing store queues.", order: 0 },
  { id: "faq-cat-digital-signage", name: "Digital Signage", icon: "tv", description: "Setting up displays, campaigns, and scheduling for digital signage.", order: 1 },
  { id: "faq-cat-getting-started", name: "Getting Started", icon: "rocket_launch", description: "Platform overview, installation, and initial set-up.", order: 2 },
  { id: "faq-cat-display-device-management", name: "Display & Device Management", icon: "devices", description: "Monitoring and managing your connected displays and devices.", order: 3 },
  { id: "faq-cat-store-sites", name: "Store Sites", icon: "storefront", description: "Context-aware localised mobile sites for every connected store.", order: 4 },
  { id: "faq-cat-3rd-party-guides", name: "3rd Party Guides", icon: "integration_instructions", description: "Connecting Google Maps, Google Business Profiles, and other integrations.", order: 5 },
  { id: "faq-cat-retail-data-management", name: "Retail Data Management", icon: "table_chart", description: "Managing store data — codes, names, addresses, and opening hours.", order: 6 },
  { id: "faq-cat-troubleshooting", name: "Troubleshooting", icon: "build", description: "Common access, login, and messaging issues.", order: 7 },
  { id: "faq-cat-appointment-bookings", name: "Appointment Bookings", icon: "event", description: "Letting customers book a time to visit without queueing.", order: 8 },
];

const articles = [
  { id: "faq-art-51000359765", categoryId: "faq-cat-queue-management", order: 0, title: "SET-UP | Enabling Virtual Store Queueing", slug: "set-up-enabling-virtual-store-queueing", summary: "The Platform allows Retailers to seamlessly introduce Virtual Queueing within any of their connected stores/branches.", keywords: ["enabling","virtual","queueing"], status: "published", bodyMd: "The Platform allows Retailers to seamlessly introduce Virtual Queueing within any of their connected stores/branches. The Steps below will walk you through how to enable virtual store queueing for each of your retail stores/branches. High Level Steps to launch Virtual Queueing: 1. Enable Store Queueing from HQ Admin 2. Define Reason for Visit categories/subcategories (these are what get selected by store visitors when they join the queue) 3. Add/Upload Retail Admin users (or set-up SAML integration for store/branch staff) 4. Enable Store Queueing for each connected Store/Branch (as required) [ADMIN USERS ONLY] STEP 1 - Enable Store Queueing within the Platform: 1. Login to HQ ADMIN & Click on PLATFORM ADMIN (bottom of the Left Hand Nav menu). 2. Click on 'Queueing / Appointments' 3. On the 'Queue Settings' page, toggle Enable Store Queueing to the ON/BLUE position (see screenshot below) 4. Leave all the Queue Management Settings as is, you can refine these settings (if required) during testing/UAT. STEP 2 - Define 'Reason for Visit' Categories/Subcategories 1. Next Click on 'Shared Settings' Tab 2. Scroll Down to the Reason for Visit Data section 3A. Add New Reason for Visits Categories (i.e. what gets selected by Visitors when they join the queue) 3B. Add New Reason for Visit Sub Categories under the Categories (if required) 4. Once again you can refine these later (learn about MORE ADVANCED SETTINGS here) NEXT STEP > ADD UPLOAD RETAIL ADMIN USERS" },
  { id: "faq-art-51000483613", categoryId: "faq-cat-queue-management", order: 1, title: "SET-UP | Upload Retail Admin Users", slug: "set-up-upload-retail-admin-users", summary: "To Add Store Managers/Staff for each of your stores, you'll need to complete the Attached Spreadsheet and save this as a .csv file.", keywords: ["upload","retail","admin","users","queueing"], status: "published", bodyMd: "To Add Store Managers/Staff for each of your stores, you'll need to complete the Attached Spreadsheet and save this as a .csv file. You'll also need to define a First Time Login password for Retail Staff to login to access the virtual queue for their respective store. Staff will be prompted to update this password on First Login to the Retail Admin site. PLEASE NOTE: We recommend setting up SAML integration for Retail Staff before rolling out the platform to a significant number of stores/branches. STEP 1 - DEFINE RETAIL ADMIN USERS 1. Open the Attached .CSV file. 2. For each Store that you've added to the Platform (or you'd like to launch Virtual Queue Management in). 3. Add the respective Store/Branch Managers/Staff Retail Admin Accounts. 4. Make sure that each of the STORE CODES added in the last column matches those defined for each of the stores within the platform. 5. Save the File as a CSV file again. STEP 2 - UPLOAD RETAIL ADMIN USERS TO THE PLATFORM 1. Login to HQ-Admin & select COMPANY SETTINGS (bottom of left hand nav menu). 2. Navigate to Retail Admin Set-up page. 3. Drag & Drop the above CSV file into the Upload Section (see screenshot below). 4. Define & Confirm the First Time Login Password that will be used by all Added Managers/Staff (they will be asked to update this password on First Login). 5. Copy & Share the Retail Admin Login link (& created credentials) with each of your Retail Staff." },
  { id: "faq-art-51000359322", categoryId: "faq-cat-queue-management", order: 2, title: "SET-UP | Adding 'Reason for Visit' Categories & Sub-Categories", slug: "set-up-adding-reason-for-visit-categories-sub-categories", summary: "When a store visitor Joins the Queue, they need to provide a Reason for their Visit.", keywords: ["adding","reason","visit","categories","queueing"], status: "published", bodyMd: "When a store visitor Joins the Queue, they need to provide a Reason for their Visit. The selected reason for visit is used to determine the serve time, which in turn is used to update the store's Estimated Wait Time for customers that join the queue after the current visitor. Reason for Visit is also used within Retail Insights to identify the most common reasons why customers are visiting stores/branches & also to track whether specific issues are being resolved or not. The attached spreadsheet, contains example Reason for Visit values for the telco & banking sectors. After installation, the platform comes pre-populated with the following 3 Category Filters. Please feel free to update these as required for your specific use case (simply select 'Manage' when viewing the Category Filters within the drop down menu): I'm a New Customer I'm an Existing Customer I'm a Business Customer This is the 1st drop down menu presented to Store Visitors. The following drop down menu is determined based on which of the above Category Filters have been assigned to the selected Filter. > Select 'ADD NEW REASON FOR VISIT CATEGORY' (e.g. Click & Collect, Category 1 & Category 2 in screenshot below) to Add New Categories. > Next, select 'ADD NEW SUB CATEGORY' if you would like additional options nested within a specific category (e.g. SubCat-001, SubCat-002 & SubCat-003 in the screenshot below) > And Finally, click on the Category Name & Add the Respective Category Filters to each of Reason for Visit Category that have been defined (see Category Filter column in screenshot below)" },
  { id: "faq-art-51000360036", categoryId: "faq-cat-queue-management", order: 3, title: "SET-UP | Updating the Platform's SMS Sender ID", slug: "set-up-updating-the-platform-s-sms-sender-id", summary: "The Platform Sends SMS Messages to Visitor's to advise them about their Status within the Queue.", keywords: ["platform","sender","queueing"], status: "published", bodyMd: "The Platform Sends SMS Messages to Visitor's to advise them about their Status within the Queue. The Default Sender of these SMS messages is your ${BrandName} (as defined within Company Settings > Brand / Logo) To Update the SMS Sender ID used by the Platform, follow the steps below: Please note that origination identities such as sender IDs have resource policies which controls which entities can access the resource. In this case I can see that the sender ID \"YOURSENDERID\", does not have any resource policy set. This means that SNS cant actually access this sender ID to send SMS messages. In order to resolve this issue, can you please follow the below: 1. Navigate to the end user messaging console. 2. Click on SMS on the left panel. 3. Click on Sender Ids in the left panel. 4. Click on your newly registered sender ID \"{YOURSENDERID}\". 5. Click on the Edit button by the Resource policy tab. 6. Please add the resource policy provided below, as I have already configured it to allow the SNS service to use the customers sender ID to send SMS messages from the AWS account \"{YOURAWSACCOUNTID}\". 7. Once this is complete, save the resource policy and retest deliveries. [AWS resource policy JSON allowing sns.amazonaws.com sms-voice:SendTextMessage]" },
  { id: "faq-art-51000359801", categoryId: "faq-cat-queue-management", order: 4, title: "SET-UP | Integrate Single-Sign-On (SAML) for Your Organisation", slug: "set-up-integrate-single-sign-on-saml-for-your-organisation", summary: "We strongly recommend ensuring that all your Store-Staff / Store-Managers are Automatically added to the Platform using your Organisation's Single-Sign-On Solution (e.g.", keywords: ["integrate","single","sign","saml","organisation","queueing"], status: "published", bodyMd: "We strongly recommend ensuring that all your Store-Staff / Store-Managers are Automatically added to the Platform using your Organisation's Single-Sign-On Solution (e.g. SAML). The Personalisation Hub Team would be happy to help you get this integration set-up within your Environment. Please Raise a New Ticket with the Subject 'SAML Integration Support' here." },
  { id: "faq-art-51000363265", categoryId: "faq-cat-queue-management", order: 5, title: "SET-UP | Set Up a Dedicated Concierge Display / Kiosk", slug: "set-up-set-up-a-dedicated-concierge-display-kiosk", summary: "To set-up a dedicated Concierge Display / Kiosk that allows Visitors to quickly Join the Queue when they enter a Store / Branch should only take a few minutes.", keywords: ["dedicated","concierge","display","kiosk","queueing"], status: "published", bodyMd: "To set-up a dedicated Concierge Display / Kiosk that allows Visitors to quickly Join the Queue when they enter a Store / Branch should only take a few minutes. Steps to set this up are as follows: STEP 1 - Create a Mobile Site Template for Your Concierge Display/Kiosk STEP 2 - Enable QR Control & Assign the Mobile Template to the Concierge Display/Kiosk Once you've followed the Steps below & set-up your Concierge Display/Kiosk Experience, you can further Personalise a Visitors experience (see following article)." },
  { id: "faq-art-51000358534", categoryId: "faq-cat-queue-management", order: 6, title: "STAFF TABLET | Login to Retail Admin Site (No SAML/SSO)", slug: "staff-tablet-login-to-retail-admin-site-no-saml-sso", summary: "How to Login to the Staff Tablet Site? If your Organisation is not using SAML/SSO, your store managers/staff will need to manually Login to the Staff Tablet (Retail Admin)…", keywords: ["staff","tablet","login","retail","admin","site"], status: "published", bodyMd: "How to Login to the Staff Tablet Site? If your Organisation is not using SAML/SSO, your store managers/staff will need to manually Login to the Staff Tablet (Retail Admin) site. Please find the steps that they will need to follow below:" },
  { id: "faq-art-51000358535", categoryId: "faq-cat-queue-management", order: 7, title: "STAFF TABLET | Update Staff Profile", slug: "staff-tablet-update-staff-profile", summary: "How do Store Staff Update their Profile?", keywords: ["staff","tablet","profile","profiles"], status: "published", bodyMd: "How do Store Staff Update their Profile? If your Organisation is not using SAML/SSO, Staff can manually update their Profile's themselves. To do this, please follow the Steps below:" },
  { id: "faq-art-51000359875", categoryId: "faq-cat-queue-management", order: 8, title: "STAFF TABLET | Update Staff Profile Photo", slug: "staff-tablet-update-staff-profile-photo", summary: "As a Default Profile Photo, a Staff Member's 'First Initial' and 'Last Initial' will be presented as White Copy within a Light Grey Circle.", keywords: ["staff","tablet","profile","photo","profiles"], status: "published", bodyMd: "As a Default Profile Photo, a Staff Member's 'First Initial' and 'Last Initial' will be presented as White Copy within a Light Grey Circle. To Change this, Staff are able to upload a Professional Photo of themselves via their Retail Admin Site. Please Note: The Uploaded Staff Member's Profile Photo will be shown on the Mobile Site when Staff Pick-Up Visitors from the Store Queue. Ensure clear guidelines are provided around what is and is not acceptable." },
  { id: "faq-art-51000359879", categoryId: "faq-cat-queue-management", order: 9, title: "STAFF TABLET | Managing & Updating Staff Status", slug: "staff-tablet-managing-updating-staff-status", summary: "Staff Availability is one of the Main Drivers when determining a Visitor's Estimated Wait Time.", keywords: ["staff","tablet","managing","status","profiles"], status: "published", bodyMd: "Staff Availability is one of the Main Drivers when determining a Visitor's Estimated Wait Time. When Staff are Assisting Visitors in the Queue, their Status is updated automatically as they Start Serving Visitors (Status Set to \"Serving Customer\") and Finish Serving Visitors (Status Set to \"Available\"). There are a number of situations, where Staff will Need to ensure that they Manually Update their Status themselves. For Example: Set Status to \"Unavailable\" once they have finished serving Customers and before they Logout for the Day (i.e. at the end of their shift) Set Status to \"Unavailable\" when they are Assisting a Visitor not in the Store Queue Set Status to \"Unavailable\" when they Take a Break during their shift When a Staff Member has their Status Set to \"Unavailable\" and they subsequently Pick-Up a Visitor from the Queue. Once they are Finished Assisting that Visitor, their Status will be returned to \"Available\". See Steps on How Staff are able to Manually Update their Status below:" },
  { id: "faq-art-51000359900", categoryId: "faq-cat-queue-management", order: 10, title: "STAFF TABLET | Update Staff's Language(s) Spoken", slug: "staff-tablet-update-staff-s-language-s-spoken", summary: "Visitors arriving in Store may not speak the Primary Language supported within your Stores (e.g.", keywords: ["staff","tablet","language","spoken","profiles"], status: "published", bodyMd: "Visitors arriving in Store may not speak the Primary Language supported within your Stores (e.g. English). In this case, Staff are able to update the Languages that they are able to Speak within their Staff Profile. Once these Languages are defined, Visitors can be moved (by the Store-Manager/Concierge) directly from the \"Waiting\" Queue to the \"On-Hold\" Queue where they are able to then get Assistance from a Staff Member that speaks their Language. See the Visitor's with Special Requests article for more information Please Note: Only the Languages spoken by Staff that are currently on shift (i.e. their Status is \"Available\" or \"Serving Customers\") will be available for Selection within the Place On Hold \"Languages Spoken\" drop down menu. Staff can update their Languages Spoken by following the Steps below:" },
  { id: "faq-art-51000358424", categoryId: "faq-cat-queue-management", order: 11, title: "QUEUEING | Manually Adding Visitor to Queue", slug: "queueing-manually-adding-visitor-to-queue", summary: "For Larger Store's that support a Concierge, they are able to quickly Add Store Visitor's to the Queue themselves as Visitor's enter the Store.", keywords: ["queueing","manually","adding","visitor","queue","managing"], status: "published", bodyMd: "For Larger Store's that support a Concierge, they are able to quickly Add Store Visitor's to the Queue themselves as Visitor's enter the Store. A Dedicated Concierge can also provide Staff with More Context that support a more personalised hand-over. Once Visitor's have been added to the Queue, Concierge can guide Visitors to relevant Zones where they can Engage with Displays (using QR Control) while they wait. All recent interactions within the Store will also be surfaced to Store Staff when they are Picked-Up from the Queue. See steps below to Manually Add a Visitor to the Queue:" },
  { id: "faq-art-51000359918", categoryId: "faq-cat-queue-management", order: 12, title: "QUEUEING | Pick-Up Visitor from Queue", slug: "queueing-pick-up-visitor-from-queue", summary: "After a Visitor has been added to the Queue, Any Staff Member can now Assist them by selecting 'Pick-Up'.", keywords: ["queueing","pick","visitor","queue","managing","queues"], status: "published", bodyMd: "After a Visitor has been added to the Queue, Any Staff Member can now Assist them by selecting 'Pick-Up'. Additional Information added to the Visitor's Queue Record can be accessed from most Queueing Pages (from the \"Waiting\", \"In-Progress\" & \"On-Hold\" queues) by simply tapping on the respective timer. See further details below:" },
  { id: "faq-art-51000359919", categoryId: "faq-cat-queue-management", order: 13, title: "QUEUEING | Place Visitor On-Hold", slug: "queueing-place-visitor-on-hold", summary: "Please Note: Placing a Visitor On-Hold Must be Enabled by Platform Admin When Enabled, Staff are able to Place Visitor's On-Hold.", keywords: ["queueing","place","visitor","hold","managing","queues"], status: "published", bodyMd: "Please Note: Placing a Visitor On-Hold Must be Enabled by Platform Admin When Enabled, Staff are able to Place Visitor's On-Hold. This allows Staff to transfer a Visitor amongst Staff with Different Skills (e.g. 'speak to the manager') & also allows Visitors to be Placed On Hold without having to Join the Queue again where they may need a short break (e.g. 'to go to the bank'). See Steps below:" },
  { id: "faq-art-51000360011", categoryId: "faq-cat-queue-management", order: 14, title: "QUEUEING | Visitor Scans QR-Code on Staff-Tablet to Join the Queue", slug: "queueing-visitor-scans-qr-code-on-staff-tablet-to-join-the-queue", summary: "To Quickly Add a Visitor to the Queue (& to allow them to use their Stored Contact Details from their Mobile Device), Staff can show the Visitor a QR-Code that will open the…", keywords: ["queueing","visitor","scans","code","staff","tablet"], status: "published", bodyMd: "To Quickly Add a Visitor to the Queue (& to allow them to use their Stored Contact Details from their Mobile Device), Staff can show the Visitor a QR-Code that will open the 'Join the Queue' form on the Visitor's Mobile. When adding Visitors to the Queue via the Staff Tablet > We Recommend getting them to Scan this QR Code. This ensures that future Interactions within the Store / Branch can be associated to the Visitor (this facilitates a more personalised/connected experience when Visitors are picked up from the Queue). Once the Visitor has Joined the Queue, Staff can then add 'Additional Information' to the Visitor's Queue record which then provides further Context for Assisting Staff. To Allow a Visitor to Join the Queue using a QR-Code, follow the steps below:" },
  { id: "faq-art-51000360012", categoryId: "faq-cat-queue-management", order: 15, title: "QUEUEING | Visitor Joins Queue by Scanning a QR-Code on a Display", slug: "queueing-visitor-joins-queue-by-scanning-a-qr-code-on-a-display", summary: "Visitor's may first wish to Browse through the Store and they may only want to Join the Queue at a later stage.", keywords: ["queueing","visitor","joins","queue","scanning","code"], status: "published", bodyMd: "Visitor's may first wish to Browse through the Store and they may only want to Join the Queue at a later stage. To support this, we recommend Enabling QR-Control on all your Displays. This allows Visitors to Join the Queue from anywhere in the Store by simply scanning the QR-Code presented on any Display. 1. First Step is to set-up a Dedicated 'Join the Queue' Template OR to Add the 'Join the Queue' Menu Option to the desired Mobile Site Template. 2. Second Step is to ensure that QR-Control (& the above 'Mobile Site Template' has been set-up on that Display)" },
  { id: "faq-art-51000360014", categoryId: "faq-cat-queue-management", order: 16, title: "QUEUEING | 'Add Additional Info' to a Visitor in Queue", slug: "queueing-add-additional-info-to-a-visitor-in-queue", summary: "The 'Add Additional Info' Feature is to ensure that Information can be Shared between Staff on the Visitor to ensure that they receive a Personalised Retail Experience.", keywords: ["queueing","additional","info","visitor","queue","managing"], status: "published", bodyMd: "The 'Add Additional Info' Feature is to ensure that Information can be Shared between Staff on the Visitor to ensure that they receive a Personalised Retail Experience. The objective is to try and ensure that Visitor's never have to repeat themselves as they are Assisted in Retail. To Add Additional Info to a Visitor's Queue record, see steps below:" },
  { id: "faq-art-51000360015", categoryId: "faq-cat-queue-management", order: 17, title: "QUEUEING | View Languages Spoken by Staff Currently on Shift", slug: "queueing-view-languages-spoken-by-staff-currently-on-shift", summary: "To Ensure Visitor's Feel Comfortable when Visiting your Stores.", keywords: ["queueing","view","languages","spoken","staff","currently"], status: "published", bodyMd: "To Ensure Visitor's Feel Comfortable when Visiting your Stores. Ensure that all Staff have updated their Staff Profile and listed the Languages that they are able to Assist Visitors in. Once these have been Updated, you are able to Start ensuring that if a Language is spoken, Visitors can be assigned to a Staff Member that speaks that Language. Promotions presented on Retail Displays can also be Targeted based on the Languages currently Spoken by Staff on Shift. To check the Languages Spoken by Store Staff, see steps below:" },
  { id: "faq-art-51000360017", categoryId: "faq-cat-queue-management", order: 18, title: "QUEUEING | Click to Copy Mobile Number / Email Address", slug: "queueing-click-to-copy-mobile-number-email-address", summary: "To Reduce Handling Time & Errors, once a Visitor's Mobile Phone Number or Email Address have been entered, these do not have to be entered again.", keywords: ["queueing","click","copy","mobile","number","email"], status: "published", bodyMd: "To Reduce Handling Time & Errors, once a Visitor's Mobile Phone Number or Email Address have been entered, these do not have to be entered again. From the Visitor's Details Page, Staff can simply click on either of these Fields to Copy this Data to their Clipboard so that it can be used in Other Downstream Systems (e.g. CRM). See Steps below:" },
  { id: "faq-art-51000360027", categoryId: "faq-cat-queue-management", order: 19, title: "QUEUEING | View Recent Interactions (& Customer Profile Data)", slug: "queueing-view-recent-interactions-customer-profile-data", summary: "Any Connected Customer Data can be Surfaced to Staff when they Pick-Up a Customer from the Queue.", keywords: ["queueing","view","recent","interactions","customer","profile"], status: "published", bodyMd: "Any Connected Customer Data can be Surfaced to Staff when they Pick-Up a Customer from the Queue. Also, Any Recent Interactions within your Store / Branch will be shown. This ensures that Staff are able to Personalise the Visitor's Interactions and ensures that any Interaction from every touch-point can be considered when tailoring their Retail Visit. See Steps below, covering how this information is Surfaced to Retail Staff:" },
  { id: "faq-art-51000360033", categoryId: "faq-cat-queue-management", order: 20, title: "QUEUEING | SMS / Text Messages sent to Visitors", slug: "queueing-sms-text-messages-sent-to-visitors", summary: "The Platform Currently sends out a number of SMS Messages to Visitors informing them of their Status within the Queue.", keywords: ["queueing","text","messages","sent","visitors","managing"], status: "published", bodyMd: "The Platform Currently sends out a number of SMS Messages to Visitors informing them of their Status within the Queue. These SMS messages are sent using AWS SES Service & by Default the Sender of the Message will be from Your Brand. If you would like to update the Sender of these Messages, see Steps below. Below is a summary of all the SMS/Text Messages sent to Visitors. Please get in touch with the Personalisation Hub Team if you would like to Customise any of the SMS/Text Messages that get sent. Added to Store Queue: Hi ${VisitorFirstName}, You've joined the Queue at ${BrandName} ${StoreName}. To track your progress click the link below ${UniqueQueueURL}. Picked-Up from Queue: Hi ${VisitorFirstName}, It's your turn! ${StaffFirstName} will be helping you today & is currently looking for you. Your Ticket Number is ${QueueTicketNumber}. Flagged as \"No Show\": Hi ${VisitorFirstName}, Unfortunately you've lost your spot in the Queue. To Update the Sender of these SMS Messages, see steps below:" },
  { id: "faq-art-51000359916", categoryId: "faq-cat-queue-management", order: 21, title: "MANAGER | View Store Queueing Stats & Staff Status Widget", slug: "manager-view-store-queueing-stats-staff-status-widget", summary: "Store Managers are provided with a Different Queueing Summary Widget to that shown to Staff.", keywords: ["manager","view","queueing","stats","staff","status"], status: "published", bodyMd: "Store Managers are provided with a Different Queueing Summary Widget to that shown to Staff. Store Managers are able to see an Overview of the Queueing Stats for the whole Store, as well as Click on specific Staff member's profile icons to see their Individual Stats. To view these, please see steps below:" },
  { id: "faq-art-51000360043", categoryId: "faq-cat-queue-management", order: 22, title: "MANAGER | Remove Visitor from the Queue", slug: "manager-remove-visitor-from-the-queue", summary: "Where a Visitor needs to be Removed from the Queue (e.g.", keywords: ["manager","remove","visitor","queue","managing","queues"], status: "published", bodyMd: "Where a Visitor needs to be Removed from the Queue (e.g. Staff forgot to finish serving them the day/night before). The Store Manager is easily able to Remove these Visitors from any of the Store Queues (Waiting, In-Progress & On-Hold). To do this, follow the steps below:" },
  { id: "faq-art-51000360044", categoryId: "faq-cat-queue-management", order: 23, title: "MANAGER | Visitor's with Any Special Requests (e.g. Language or Business Customer)", slug: "manager-visitor-s-with-any-special-requests-e-g-language-or-business-customer", summary: "You will have Visitors that have Unique Requests (depending on your business-type).", keywords: ["manager","visitor","special","requests","language","business"], status: "published", bodyMd: "You will have Visitors that have Unique Requests (depending on your business-type). To support these Cases, a Store Manager is able to Directly Move a Visitor from the \"Waiting\" Queue, to the \"On-Hold\" queue where they can be Assisted by the Most Appropriate Staff Member. To do this, please see steps below:" },
  { id: "faq-art-51000290754", categoryId: "faq-cat-3rd-party-guides", order: 0, title: "Connect Platform to Google Maps / Places", slug: "connect-platform-to-google-maps-places", summary: "Platform User Type: ADMIN ONLY First you will need to Create an API Key for your Organisation to access Google Maps / Places.", keywords: ["connect","platform","google","maps","places"], status: "draft", bodyMd: "Platform User Type: ADMIN ONLY First you will need to Create an API Key for your Organisation to access Google Maps / Places. For More information on how to do this Click Here. Once you have your Organisation's Google Maps API Key: Login to Personalisation Hub Navigate to PLATFORM ADMIN > Platform Integrations > Google Maps/Places Paste your Organisation's Google Maps API Key Select 'Save Changes' Validate Google Maps API Key: Navigate to STORES / BRANCHES Select 'Add New Store' Scroll Down and select 'Find Address' (shown above the Address Fields) A Pop-Up Address/Places Finder should be shown Enter your Business Names/Addresses If you see results from Google then your Google Maps API Key is working correctly Select 'Cancel' at the bottom of the Screen once completed" },
  { id: "faq-art-51000290791", categoryId: "faq-cat-3rd-party-guides", order: 1, title: "Obtaining your Google Business Profile API Credentials", slug: "obtaining-your-google-business-profile-api-credentials", summary: "Please Note: You will need a Google Approved API to access your Organisation's Google Business Profile Data.", keywords: ["obtaining","google","business","profile","credentials","profiles"], status: "draft", bodyMd: "Please Note: You will need a Google Approved API to access your Organisation's Google Business Profile Data. Only a Single API will be approved by Google (per Organisation). Click here for more information. 1. Login to your Organisation's Google API Dashboard 2. Select the Respective Project from the drop-down in the top menu bar then select Credentials in the left hand column 3. Click on the Google Business Profile (Auth 2.0 Client ID) that has been approved by Google to access your organisation's GBP Listings 4. In the top right corner of this Screen you will find your Client ID & Client Secret, please note these down some where secure 5. You will also need to add an Authorised redirect URL for your Personalisation Hub Platform instance [YOUR_PH_DOMAIN]/location-api/auth/google/callback" },
  { id: "faq-art-51000290793", categoryId: "faq-cat-3rd-party-guides", order: 2, title: "How to Back-up your Google Business Profile Data", slug: "how-to-back-up-your-google-business-profile-data", summary: "This Document Outlines the simple steps required to back-up your GBP Store Data: 1.", keywords: ["back","google","business","profile","data","profiles"], status: "draft", bodyMd: "This Document Outlines the simple steps required to back-up your GBP Store Data: 1. Login to your Google Business Profiles Dashboard using your Organisation's authorised GMB credentials 2. Select all Stores by clicking on the Select-All check-box (please double-check that all Stores have been selected) 3. Select the 'Actions' drop down menu item (top right of Store Table) 4. Select Download 'Locations' to take a back-up of all the selected Stores/Locations 5. Finally select the Desired Store Data that you would like to back up, select the Desired Format and select Download 6. Save the file in a secure location (ideally with your other regular back-ups of your Store Data)" },
  { id: "faq-art-51000290792", categoryId: "faq-cat-3rd-party-guides", order: 3, title: "Connecting Platform to Google Business Profiles", slug: "connecting-platform-to-google-business-profiles", summary: "1. Login to the Platform's HQ Admin site 2. Select PLATFORM ADMIN > API AUTHENTICATION > ADD NEW PLATFORM 3. Create a New Secret/Token that is used to Authenticate GBP with the…", keywords: ["connecting","platform","google","business","profiles"], status: "draft", bodyMd: "1. Login to the Platform's HQ Admin site 2. Select PLATFORM ADMIN > API AUTHENTICATION > ADD NEW PLATFORM 3. Create a New Secret/Token that is used to Authenticate GBP with the Platform, using a descriptive name (e.g. Google Business Profile). 4. Select PLATFORM ADMIN > GOOGLE BUSINESS PROFILE > CONNECT PLATFORM WITH GOOGLE 5. Now enter all your GBP Credentials that you noted down from the Google API Dashboard (Client ID & Client Secret), select the Secret/Token that you created above from the Drop Down menu and press 'Save Changes' 6. Next Step is to Authenticate the Platform with GBP, press the 'Authenticating with Google Business Profile' button. Select the appropriate Google Account & if required go through the Authentication/Login process 7. Google will request permission to Grant your instance of Personalisation Hub with access to your Google Business Profile Listings, select Allow 8. Your Platform is now connected to Google Business Profiles, you can stop here, or follow the Steps below to select which Stores you would like to Synchronise with the Platform. 9. If you would like to Synchronise your Stores now, select Manage Synchronised Stores 10. Select Sync Store Data from Google Business Profile 11. Once loaded, use the 'select all' check-box OR go through and select the individual Stores that you would like to Synchronise. Once selected Press the Right Arrow Icon (this adds the Stores to the Sync list). BEFORE FOLLOWING THE NEXT STEPS! Please ensure that you have Taken a BACK-UP of all your GBP Store Data. 12. Select the 'I confirm that I have taken a back-up of the data' check-box. 13. The Stores that you selected in the Steps above will now be Synchronised with the Platform. Once completed, select Done 14. Now when you visit the STORES / BRANCHES section, all your GBP Stores should be listed." },
  { id: "faq-art-51000290749", categoryId: "faq-cat-3rd-party-guides", order: 4, title: "Create New API Authentication Credentials for Integration", slug: "create-new-api-authentication-credentials-for-integration", summary: "Platform User Type: ADMIN ONLY Create a New API Key for New Platform Integration that you would like to set-up.", keywords: ["create","authentication","credentials","integration","other","party"], status: "draft", bodyMd: "Platform User Type: ADMIN ONLY Create a New API Key for New Platform Integration that you would like to set-up. If you plan to integrate Personalisation Hub with Several External Platforms, we recommend setting up all the Secrets/Tokens required for these integrations now. Login to Personalisation Hub Go to PLATFORM ADMIN > Platform Integrations > API Authentication Select Add New Platform Provide a Platform Name (e.g. AEM & Kiosk Players, Google Business Profile, etc) Select the COPY Icon and Save Secret/Token on your Computer Select 'Save'" },
  { id: "faq-art-51000325539", categoryId: "faq-cat-3rd-party-guides", order: 5, title: "Glossary", slug: "glossary", summary: "List of words terms that may need clarification.", keywords: ["glossary","other","party","platforms"], status: "draft", bodyMd: "List of words terms that may need clarification. This may be one which needs to be revisited from time to time until we have an exhaustive list of terms. Rob and I will discuss what constitutes a Glossary term in the AEM Screens/PH context. Campaigns Experiences Resolve Audience Segment Activity Display Screen Device Player Location Fixed Store segment Variable Store segment Formatted Store Segments Out of Hours Campaigns Highlight vs Select (when creating folders or files as opposed to publishing or modifying a folder or file)" },
  { id: "faq-art-51000325086", categoryId: "faq-cat-3rd-party-guides", order: 6, title: "CHROME | Setting Up a New Organisational Unit (OU) in Google CDM", slug: "chrome-setting-up-a-new-organisational-unit-ou-in-google-cdm", summary: "To effectively manage your display network using ChromeOS devices, Google's Chrome Device Management solution is the tool of choice.", keywords: ["chrome","setting","organisational","unit","google","device"], status: "draft", bodyMd: "To effectively manage your display network using ChromeOS devices, Google's Chrome Device Management solution is the tool of choice. This platform enables remote device management once a ChromeOS device has been registered with your organization's enterprise Google account. By leveraging Organizational Units, you can define the settings that each device will adopt. Before you start, ensure that you have a Google Workspace account with super admin access. Part 1: Creating a New Organisational Unit - Sign in to your Google Admin console; go to Directory > Organisational units; click the + button to create a new organisational unit; enter a name and optional description; click Create. Part 2: Defining Device Settings - Go to Devices > Chrome Devices; click on the organisational unit you've just created; click Settings > Device settings. Settings include: Sign-in Settings; User & Browser Settings; Device Update Settings; Kiosk Settings (set up devices to run in kiosk mode and manage kiosk applications). Always test new settings with a small number of devices before applying them to all devices. We recommend creating an overall folder for your Screens Project ({BrandName} Screens), separate folders for each Environment (Development, Stage & Production), and additional folders for each Display Type (referred to as OUs). To register a Chrome Device against an OU: Expand Devices > Chrome > Apps & extensions > Kiosks; define the Kiosk App & Settings; select the Yellow PLUS Icon and Add the Kiosk Player that should be used." },
  { id: "faq-art-51000325427", categoryId: "faq-cat-3rd-party-guides", order: 7, title: "LOCAL | Installing AEM Screens Player on Mac/PC", slug: "local-installing-aem-screens-player-on-mac-pc", summary: "tbd", keywords: ["local","installing","screens","player","chrome","device"], status: "draft", bodyMd: "tbd" },
  { id: "faq-art-51000343747", categoryId: "faq-cat-3rd-party-guides", order: 8, title: "CHROME | Registration a Chromebox with Google CDM & Assigning your Kiosk App", slug: "chrome-registration-a-chromebox-with-google-cdm-assigning-your-kiosk-app", summary: "Before you start, ensure that the Chromebox device is ready, with a working internet connection, and that you have a Google Workspace account with super admin access.", keywords: ["chrome","registration","chromebox","google","assigning","kiosk"], status: "published", bodyMd: "Before you start, ensure that the Chromebox device is ready, with a working internet connection, and that you have a Google Workspace account with super admin access. Part 1: Registering Chromebox with Google Chrome Device Management (CDM) - Turn on the Chromebox device; follow the on-screen instructions until you see the sign-in screen (don't sign in yet); press Ctrl+Alt+E to enter enrollment; enter the username and password from your Google Workspace account, then click Enroll device; the device will register and connect to CDM; sign in to your Google Workspace account to manage your device. Part 2: Launching a Kiosk App - Sign in to your Google Admin console; go to Devices > Chrome Devices; click on the device, then Device settings; scroll to Kiosk Settings > Manage Kiosk Applications; in the Kiosk Applications panel click Chrome Web Store and enter the ID of the Kiosk App; click Add then Save; scroll to Kiosk Settings > Auto-Launch Kiosk App and enter the ID of the Kiosk App to auto-launch; click Save. The app will now automatically launch whenever the device starts up." },
  { id: "faq-art-51000290830", categoryId: "faq-cat-getting-started", order: 0, title: "EXECUTIVE SUMMARY | About Personalisation Hub?", slug: "executive-summary-about-personalisation-hub", summary: "Executive Summary: The Personalisation Hub Platform was created to allow Brands to easily launch Localised & Personalised Campaigns across every touchpoint.", keywords: ["executive","summary","personalisation","hub?"], status: "published", bodyMd: "Executive Summary: The Personalisation Hub Platform was created to allow Brands to easily launch Localised & Personalised Campaigns across every touchpoint. The Team has decades of experience (working with Brands) to ensure they are able to support personalisation across all owned channels, in real-time (including in-store). The Platform addresses the biggest obstacles that Brands face when trying to continually support localised & personalised campaigns/experiences. Our Why? As 3rd Party Cookies fade away, existing Personalisation solutions become less effective. Enterprises have made substantial investments in (1) Big Data (2) CDPs / CRM & (3) AI / ML but are currently unable to easily activate this data/insights. Existing MarTech solutions are decades old (Siloed/Outdated/Expensive/Complex to maintain). Platform Strategy: Self-Hosted (own domain/data/cookies) & Fully Secure; Single Platform that supports OmniChannel Personalisation; Designed from Day One for AI / Real-Time (built-in AI-models/agents support continuous optimisation from campaign brief to automated creative variation optimisation). Team's Focus (2025): Simplify integrations; Auto create variations; Continually optimise creative. The Platform's mission is to create an ecosystem that allows brands to seamlessly plan, create, and launch localised & personalised experiences across every touchpoint." },
  { id: "faq-art-51000495815", categoryId: "faq-cat-getting-started", order: 1, title: "USE CASES | Overview of Use Cases supported by Personalisation Hub", slug: "use-cases-overview-of-use-cases-supported-by-personalisation-hub", summary: "Personalisation Hub is an enterprise-grade personalisation platform designed to help brands seamlessly personalise customer experiences across all owned touchpoints (website,…", keywords: ["cases","overview","supported","personalisation","executive","summary"], status: "published", bodyMd: "Personalisation Hub is an enterprise-grade personalisation platform designed to help brands seamlessly personalise customer experiences across all owned touchpoints (website, mobile app & in-store). The platform runs 100% on AWS, securely within a client's own Virtual Private Cloud (VPC) environment, ensuring complete control over their data, security & compliance. This allows clients to securely activate customer/AI data to drive personalised experiences across all their enabled touchpoints. The platform supports a wide range of features designed and developed to ensure retail brands are able to support Personalisation in Retail: Retail Data Management - create a single source of truth for retail data to ensure all retail data (e.g. store opening hours) is always accurate. Virtual Queue Management - ensure customers are not forced to stand in a physical line when they arrive in-store. Appointment Bookings - ensure customers can arrange a time that works for them (e.g. collect an item purchased online). Digital Signage - platform allows clients to support enhanced experiences in-store by providing a world-leading digital signage solution that is (1) self-hosted and (2) runs on the client's own domain, opening up new opportunities to let customers interact & engage with displays (supporting 1:1 personalisation). Example use cases by industry: 1. Support a Connected & Personalised Retail Experience (e.g. Telco, Banking, Bricks & Mortar Retail) - join a virtual queue or book an appointment (BOPIS/Click & Collect); obtain consent to leverage customer data; unified personalisation profile aggregated from connected platforms (CDP, CRM, AI/ML Models, Amazon Personalise, Amazon Connect); connected customer journey (Web > App > In-Store); leverage dynamic QR codes to support 1:1 personalisation; QR Control turns the customer's mobile into a remote control for the display; supports AR/MR (magic mirror); Staff Tablet interface surfaces Next Best Actions (NBA). Business Benefits: Reduced Customer Wait Times & Higher NPS; More Engaging & Effective In-Store Conversations; Unified Cross-Channel Experiences; Higher Sales Conversion; Enhanced Customer Retention. 2. Leverage 1st Party Data/Audiences to Target Campaigns on Digital Signage in-store (Retail Media) - self-hosted retail media network; customers with the retailer app auto checked-in on arrival (MIST/vBLE integration, now owned by Juniper/HPE); connected customer journey; dynamic QR codes for store check-in; assign ad slots for programmatic advertising (coming soon). Business Benefits: Increased Basket Size & Conversion; Monetisation of In-Store Media; Improved Customer Experience; Closed-Loop Attribution; Real-Time Campaign Agility. 3. Trigger Hyper-Localised (Geo-Targeted) Campaigns on Digital Signage (QSR Industry) - Day Parting (Advanced Scheduling); integrate local weather/events/stock availability; Personalised Offers (1:1); Vision @ the Edge (audience sensing - age/gender estimation, hardware dependent). Business Benefits: Increased Sales per Visit; Improved Operational Efficiency; Higher Customer Engagement & Loyalty; Data-Driven Campaign Optimisation; Waste Reduction." },
  { id: "faq-art-51000290582", categoryId: "faq-cat-getting-started", order: 2, title: "PRE-INSTALLATION CHECK-LIST", slug: "pre-installation-check-list", summary: "We recommend gathering the information covered below & lining up internal resource that may be required (e.g.", keywords: ["installation","check","list","platform","setup"], status: "published", bodyMd: "We recommend gathering the information covered below & lining up internal resource that may be required (e.g. your webmaster) before you start the platform installation. 1. Master Admin User's Email Address (e.g. ITAdmin@yourdomain.com) - used as the Master Admin login & to manage Platform Hibernation and Cost Control options. 2. Platform URL (this can't be changed) - e.g. dev.ph.[YourCompanyDomain.com], staging.ph.[...], ph.[...]. Used for 1st party cookies. IT resource should be available to update DNS records immediately after install. 3. Platform Email Address - a company managed email address used as the \"Sender\" of Platform emails (e.g. personalisationhub@YourCompanyDomain.com). Must be defined & verified; AWS SES account must be promoted out of sandbox mode. Updated via COMPANY SETTINGS > Platform Set-up. 4. Google Maps API Key - for Google Address/Places lookups. Added via PLATFORM ADMIN > Platform Integrations > Google Maps/Places. 5. Your Company Logos/Icons (Transparent PNGs OR SVGs) - versions for dark and light backgrounds, uploaded via COMPANY SETTINGS > Brand / Logo. 6. Retail Admin Users - CSV file of Store Managers/Staff [email address, first name, last name, role & store code]. Role should be STAFF or STORE_MANAGER. Store Code must match the Store Code defined when adding Locations/Stores. Uploaded within COMPANY SETTINGS > Retail Admin Set-up. NEXT STEP > PLATFORM INSTALLATION WIZARD" },
  { id: "faq-art-51000481977", categoryId: "faq-cat-getting-started", order: 3, title: "STEP 1 - DEPLOY PLATFORM THROUGH AWS MARKETPLACE", slug: "step-1-deploy-platform-through-aws-marketplace", summary: "The Personalisation Hub platform is available for a 30 Day Free Trial (cancel anytime).", keywords: ["step","deploy","platform","through","marketplace","installation"], status: "published", bodyMd: "The Personalisation Hub platform is available for a 30 Day Free Trial (cancel anytime). This deployment guide supports installation in a single-AZ, single-region configuration. For multi-AZ or multi-region deployment, contact us. Follow the steps below to install the platform into your own AWS Environment: 1. Search for 'Personalisation Hub' in the AWS Marketplace. 2. Select 'View Purchase Options'. 3. Scroll to the bottom and select 'Subscribe'. 4. Select your Desired Fulfilment Option (CloudFormation Template) & Region, then 'Continue to Launch'. 5. Check details and select 'Launch'. 6. On the create stack page select 'Next'. 7. On specify stack details, provide a stack name (Max 12 characters, all lower-case, following the naming convention). Copy 0.0.0.0/0 into the three 'CIDR' fields, then 'Next'. 8. Scroll down and select 'Next' (Notice about created IAM resources - template provisions IAM roles, users, groups and policies for Terraform-based provisioning and ongoing operations/upgrades; scoped to the current stack; named with Stack Name & Stack ID prefix). 9. Scroll to the bottom and select 'Submit'. 10. It takes around 3-4 minutes for the new stack to be created. NEXT STEP > PLATFORM INSTALLATION WIZARD" },
  { id: "faq-art-51000462323", categoryId: "faq-cat-getting-started", order: 4, title: "STEP 2 - PLATFORM INSTALLATION", slug: "step-2-platform-installation", summary: "Install the platform from AWS Marketplace (STEP 1) OR using the provided CloudFormation template (.yml file).", keywords: ["step","platform","installation","setup"], status: "published", bodyMd: "Install the platform from AWS Marketplace (STEP 1) OR using the provided CloudFormation template (.yml file). The stack takes around 4 minutes to create. From the new CloudFormation stack, select the 'Outputs' tab and click the link next to 'EC2InstancePublicURL' to open the Installation Wizard. (This link also gives future access to the Cost Control Settings.) STEP 1 - Create Master Admin account: Company/Brand Name (used as ${BrandName} token in external comms, aligned to Google Maps store naming); Master Admin Email address; Master Admin Password; Accept Ts&Cs & select 'Create Master Account'. STEP 2 - Login to the Installation Wizard using Master Admin Account. STEP 3 - Define Environment Type/Size, Platform Domain & add Google Maps Key. Environment Type (Development, Staging or Production - determines instance sizes); Environment Size (start 'Low', increase later via Cost Control); Platform Domain (e.g. ph.{yourprimarydomain}.com - cannot be changed once set, enables 1st party data/cookies across touchpoints); Google Maps API Key; select 'Install Platform'. STEP 4 - Platform Installation (typically ~55 minutes; Master Admin receives 'Installation Complete > Next Step: DNS Set-Up' email; forward to webmaster). Two new CNAME records required. DNS Setup must be done within 3 days as the AWS Certificate only lasts 3 days. STEP 5 - DNS Set-Up (forward email to webmaster; countdown timer shows time until certificate expires; 'Verify Domain' once DNS records set up). STEP 6 - DNS Settings have Propagated (2nd email 'DNS has been set up > Final Step: Login & Add Users'; Cost Control Settings page with Scale Up/Down and Hibernation settings for Dev & Staging; 'Login to Personalisation Hub'). STEP 7 - Login to your instance (Master Admin Email/Password; update password on first login). NEXT STEP: FIRST TIME PLATFORM LOGIN" },
  { id: "faq-art-51000463143", categoryId: "faq-cat-getting-started", order: 5, title: "STEP 3 - FIRST TIME LOGIN > PLATFORM SET-UP", slug: "step-3-first-time-login-platform-set-up", summary: "Once DNS is set up, log in to HQ ADMIN. Update your password (Master Admin - use a very secure password). 1. Platform Welcome Screen - select 'Finalise Platform Set-up' (taken…", keywords: ["step","first","time","login","platform","installation"], status: "published", bodyMd: "Once DNS is set up, log in to HQ ADMIN. Update your password (Master Admin - use a very secure password). 1. Platform Welcome Screen - select 'Finalise Platform Set-up' (taken to COMPANY SETTINGS > Platform Set-Up). 2. COMPANY SETTINGS > Platform Set-Up - CRITICAL: Platform Email Address (Platform Sender email; required before adding new Platform Users). Email Address Verification (AWS sends a verification email; click link; status shows 'Verified'). SES Sandbox mode (raise a ticket to promote SES account from sandbox to Production access). Email Sender Name (default '${BrandName} Retail'). For Virtual Queueing/Appointments, follow AWS process to send SMS (transactional only - join queue, your turn, missed turn, appointment confirmations). Approval to send SMS Messages (raise a ticket). Register SMS SenderID (Platform Sender shown in SMS). AWS SES Region. Press 'Save Changes' (prompted for Admin password). 3. Common Issues - Email Address Verification (template response to AWS Support explaining transactional/operational use of SES). SMS Sender Verification (template response for new AWS customers). SMS Sending Rejected - 2nd Time (raise support ticket support@personalisationhub.com for a Twilio work-around; open a Twilio account first). Settings that can be defined later: Add Admin Users; Add Marketing Users (restricted Company Settings/Platform Admin); Add Helpdesk Users (basic access to Retail Store Info and Displays & Devices status); Helpdesk Phone Number; Support Email Address(es); Privacy Policy URL (add before launching Queueing or Appointments publicly). NEXT STEP: UPLOAD LOGOS/ICONS" },
  { id: "faq-art-51000360304", categoryId: "faq-cat-getting-started", order: 6, title: "STEP 4 - UPLOAD LOGOS / ICONS", slug: "step-4-upload-logos-icons", summary: "To customise your instance of Personalisation Hub, check/update your organisation's Brand Name, define your Primary Business Category & upload Transparent PNG versions of your…", keywords: ["step","upload","logos","icons","platform","installation"], status: "published", bodyMd: "To customise your instance of Personalisation Hub, check/update your organisation's Brand Name, define your Primary Business Category & upload Transparent PNG versions of your company logos & icons. These are used across HQ Admin, Retail Admin, Mobile Site and Platform Emails. Steps: Login to HQ-Admin; Navigate to COMPANY SETTINGS > Brand / Logo; Check/Update your Brand Name; Select your Primary Business Category from the drop down; Select 'Save Changes'; Scroll down and Upload Transparent PNG versions of your Company Logo & Icon (first two used on Dark Backgrounds, final two used on Light Backgrounds). NEXT STEP: ADD NEW STORES" },
  { id: "faq-art-51000483547", categoryId: "faq-cat-getting-started", order: 7, title: "STEP 5 - ADD NEW STORES (from Google Places)", slug: "step-5-add-new-stores-from-google-places", summary: "Once you've added Company Logos & Icons, add some of your retail stores/branches to the Platform (Google Maps API Key required).", keywords: ["step","google","places","platform","installation","setup"], status: "published", bodyMd: "Once you've added Company Logos & Icons, add some of your retail stores/branches to the Platform (Google Maps API Key required). 1. Click STORES / BRANCHES in the Left Hand NAV Menu. 2. A pop-up modal allows you to add initial test stores/locations. 3. Your ${BrandName} is used to find close-by Stores, OR select Add Stores Manually. 4. Tick all the Stores you want to Add. 5. Select 'Add Stores'. 6. Each selected Store is added. 7. Edit each Store - remove the Brand Name and add your organisation's Unique Store Code (required when adding Retail Admin users to associate staff to specific stores). 8-11. Open the Store Details page, delete the Brand Name from the Store's Name, add the Unique Store Code, Save Changes. Repeat for each store. NOTE: In Production, connect to Google via the Google Business Profile API so store data updates synchronise with Google Maps/Places." },
  { id: "faq-art-51000463209", categoryId: "faq-cat-getting-started", order: 8, title: "STEP 6 - PLATFORM SECURITY (ENABLE IP-RESTRICTIONS)", slug: "step-6-platform-security-enable-ip-restrictions", summary: "Once installed, enable IP restrictions to control access.", keywords: ["step","platform","security","enable","restrictions","installation"], status: "published", bodyMd: "Once installed, enable IP restrictions to control access. URGENT: add your current IP address first, otherwise you will lose access. Option 1: PLATFORM BEHIND CDN PROVIDER (e.g. Akamai) - place instances behind your CDN; set up the DNS record within the CDN; control all traffic; manage IP restrictions from a single location; whitelist only CDN IP Addresses; whitelist certain public paths required for Mobile Store Sites, Virtual Queue Management & Appointment Bookings. Option 2: WHITELIST IP ADDRESSES - manage all IP addresses with access. 1. Navigate to PLATFORM ADMIN > Security (IP Restrictions). 2. Select 'Add New IP Address' (add your current IP first). 3. Add remaining IP addresses. To disable IP restrictions, tick 'Select All' and 'Deactivate selected' (when no IPs are defined/activated the feature is disabled)." },
  { id: "faq-art-51000496157", categoryId: "faq-cat-getting-started", order: 9, title: "AWS DEPLOYMENT | PREREQUISITES", slug: "aws-deployment-prerequisites", summary: "1. Required Skills and Knowledge - the deployment guide supports non-technical users with step-by-step instructions for launching via AWS Marketplace. For ongoing maintenance:…", keywords: ["deployment","prerequisites"], status: "published", bodyMd: "1. Required Skills and Knowledge - the deployment guide supports non-technical users with step-by-step instructions for launching via AWS Marketplace. For ongoing maintenance: basic familiarity with AWS Services (IAM, EC2, S3, VPC & Networking, CloudFormation); understanding AWS Marketplace (subscribing, deployment docs/release notes, monitoring usage); Domain & SSL awareness (DNS to custom domains, SSL/TLS certificates and propagation time). 2. AWS Account Access & Permissions - no root credentials required; use an IAM user/role able to: Subscribe to AWS Marketplace products; Deploy via CloudFormation; Request service quota increases; View billing/usage; create and manage required infrastructure: IAM (Roles, Policies, Instance Profiles, OIDC Provider), EKS (Cluster, Node Groups, Add-ons VPC CNI/CSI), EC2 (Launch Templates, Auto Scaling Groups, Elastic IPs), VPC (Subnets, Route Tables, NAT, Internet Gateway, NACLs, DHCP Options), Amazon RDS, Amazon ElastiCache (Redis), Amazon MSK (Kafka), OpenSearch Service, S3, Elastic Load Balancing, ACM (Certificates), KMS (Keys, Aliases), SSM Parameters. 3. Domain Name System (DNS) Mapping - configure a public DNS record pointing to the load balancer/public endpoint using your DNS provider, Cloudflare or Route 53. Recommended to use a subdomain (e.g. ph.yourdomain.com) with CNAME or A/ALIAS records. Essential for user access and HTTPS via SSL/TLS. DNS changes may take time to propagate." },
  { id: "faq-art-51000496158", categoryId: "faq-cat-getting-started", order: 10, title: "AWS DEPLOYMENT | ARCHITECTURE", slug: "aws-deployment-architecture", summary: "1. Introduction - the Installation Wizard (IW) is a one-click installation solution that provisions the full Personalisation Hub (PH) stack into the customer's AWS account. 2.…", keywords: ["deployment","architecture"], status: "published", bodyMd: "1. Introduction - the Installation Wizard (IW) is a one-click installation solution that provisions the full Personalisation Hub (PH) stack into the customer's AWS account. 2. Installation Wizard. 3. Personalisation Hub - 3.1 High-Level Architecture: micro-services, distributed, modular and scalable. Primary Platform Components: Auth Api (authenticate users & manage roles/permissions); Campaign Mobile & Campaign Api (Campaign Repository, localised/personalised by Store/Display/Visitor); Retail Admin (Store Staff/Managers view/update Retail Data, control localised campaign playback, manage Queue/Appointments); HQ Admin (manage and deliver localised/personalised campaigns across Stores/Displays/Campaign-Sites/Store-Tablets); Orchestration Layer (manage Retail Hardware, Experience Software/CMS, 3rd party integrations, visitor identification); Store Queuing; JCR (integration layer to Adobe Experience Manager, calls AEM's Java Content Repository API); Location API (localised data + Visitor API to match customer data to Displays/Devices); MIST (proximity targeting); Background Task (daemon/scheduler); Monitoring Tools (Prometheus, Grafana); Location Toolkit (receive campaign playback data, warnings, performance reporting); Squid proxy; Adobe Experience Manager (AEM content/interactions). 3.1.2 AWS Services Utilised: EKS, RDS (PostgreSQL), S3, KMS, ElastiCache for Redis, MSK (Kafka), SNS (Email/SMS), Elasticsearch/OpenSearch. 3.2 Rationale: Simplify Kubernetes Management; Scalability and High Availability; Integration with AWS Services; Security and Compliance (IAM, VPC isolation, encryption, audit logging, CloudTrail); Flexibility and Portability; Continuous Deployment and Automation (CI/CD); Cost Optimisation." },
  { id: "faq-art-51000496164", categoryId: "faq-cat-getting-started", order: 11, title: "AWS DEPLOYMENT | RESOURCE PROVISIONING", slug: "aws-deployment-resource-provisioning", summary: "Covers: 1. Available regions - PersonalisationHub stack supports all current and future commercial AWS Regions, excluding AWS GovCloud (US) and AWS China Regions (North…", keywords: ["deployment","resource","provisioning"], status: "published", bodyMd: "Covers: 1. Available regions - PersonalisationHub stack supports all current and future commercial AWS Regions, excluding AWS GovCloud (US) and AWS China Regions (North America, Europe, Asia Pacific incl. Sydney/Melbourne/Auckland, Middle East & Africa, South America). 2. Network Configuration - deployment provisions a fully managed, secure network environment automatically: VPC, public/private subnets across multiple AZs, Internet Gateway (IGW) and NAT Gateway, Route Tables, NACLs, Security Groups tailored per service (RDS, EKS, ElastiCache). 3. Instance Metadata Service (IMDS) - supports IMDSv2 per AWS best practices; EKS Worker Nodes require IMDSv2 (enforced by default in launch template); Installation Wizard EC2 and PH EC2 support IMDSv2 (optional). Customers can disable IMDSv1 and enforce IMDSv2. 4. IAM Roles and Policies - provisioned automatically by CloudFormation. Roles & Instance Profiles: EC2InstanceRole, EC2InstanceProfile, TerraformPermissionIAMUser, TerraformPermissionIAMGroup. Managed policies: DescribeOwnStackPolicy, AllowDescribeTagsForOwnStackPolicy, TerraformProvisioningPolicyEC2, TerraformPermissionIAMManagedPolicy, TerraformPermissionIAMManagedLogging. Inline policies (EC2InstanceRole): PushToECR, and TerraformProvisioningPolicy for ELB, S3, RDS, EKS, OpenSearch, ElastiCache, Kafka, DynamoDB (state locking), AutoScaling, ACM, IAM, SSMs, KMS. 5. Access Credentials and KMS Keys - IAM Access Key for TerraformPermissionIAMUser (stored securely within installer, not exposed); KMS keys: cluster-kms-key (EKS - encrypts Kubernetes secrets and EBS volumes), ph-kms-key (RDS, MSK, ElastiCache). 6. Secrets Management - secrets stored in installer's internal config files (no AWS Secrets Manager), injected as env vars or mounted files; only specific IAM roles can read at runtime; no hardcoded secrets in version control/logs; no SSH-level access or manual rotation guide yet. 7. Customer Data Storage - Application DB: Amazon RDS (PostgreSQL); Media assets: Amazon S3; Event logs/diagnostics: OpenSearch/S3; In-memory: ElastiCache (Redis). All within private subnets where applicable, protected by security groups and IAM. 8. Data Encryption - At rest: RDS (KMS CMK ph-kms-key), S3 (SSE-S3), EBS (cluster KMS key), MSK (ph-kms-key), ElastiCache (KMS). In transit: TLS for RDS/MSK/ElastiCache; external endpoints HTTPS via ACM. No LUKS/custom disk encryption (uses AWS-native EBS+KMS). 9. Public Resource Disclosure - Public ALB (main entry point, HTTPS/443); Amazon S3 bucket with public-read ACL (only specific objects exposed); ACM + Route 53/External DNS (TLS + DNS); Internet Gateway & NAT Gateway." },
  { id: "faq-art-51000496186", categoryId: "faq-cat-getting-started", order: 12, title: "AWS DEPLOYMENT | TESTING & TROUBLESHOOTING", slug: "aws-deployment-testing-troubleshooting", summary: "1. Post-Deployment Validation - 1.1 Installation Wizard (retrieve URL from EC2InstancePublicIP output of the CloudFormation stack: Console > Stacks > [Your Stack] > Outputs;…", keywords: ["deployment","testing","troubleshooting"], status: "published", bodyMd: "1. Post-Deployment Validation - 1.1 Installation Wizard (retrieve URL from EC2InstancePublicIP output of the CloudFormation stack: Console > Stacks > [Your Stack] > Outputs; should be accessible in browser once instance is up). 1.2 PersonalisationHub (after DNS mapping, wait for confirmation email with CTA link to log in; redirects to HQ Admin login; DNS/SSL may take minutes to propagate). 1.3 EKS Cluster Check (EKS Console > Clusters > [Cluster] > Workloads > Pods; ensure all pods Running). 1.4 OpenSearch Status (OpenSearch Console > Domains; verify Active and endpoint reachable). 1.5 RDS / ElastiCache / MSK (use respective consoles to check status). 2. Common Troubleshooting Scenarios: Installation Wizard URL not loading > check EC2 instance state and public DNS name; Wizard load balancer not responding > verify load balancer health checks and security groups; PH services not launching > confirm pod health in EKS Console > Workloads; OpenSearch endpoint unreachable > check domain status and access rules; Unexpected billing charges > revisit Cost Control settings to confirm schedule and size config." },
  { id: "faq-art-51000496197", categoryId: "faq-cat-getting-started", order: 13, title: "AWS DEPLOYMENT | LIFECYCLE MANAGEMENT", slug: "aws-deployment-lifecycle-management", summary: "1. Cost overview - 1.1 Licensing and Cost Model: available via AWS Marketplace (license pricing/billing terms there); license fee covers software only, AWS infrastructure…", keywords: ["deployment","lifecycle","management"], status: "published", bodyMd: "1. Cost overview - 1.1 Licensing and Cost Model: available via AWS Marketplace (license pricing/billing terms there); license fee covers software only, AWS infrastructure billed separately. 1.2 Billable AWS Services (mandatory unless noted): EC2, EKS, RDS (PostgreSQL), S3, ElastiCache (Redis), MSK, OpenSearch, ACM, IAM, CloudWatch, KMS, ELB (ALB/NLB), NAT Gateway; Route 53 optional. 2. Resource Sizing and Cost Control - 2.1 Environment Size Presets (EKS Worker Node instance type): Just Functional (t3.medium - testing/POC), Low (t3.large - light production), Medium (t3.xlarge - typical production), High (t3a.2xlarge - high-traffic). 2.2 Scheduled Uptime Optimization: define Scale Down/Scale Up times by local timezone, optionally Scale Down over weekends (Dev/Staging; primarily EC2-based services). 3. AWS Service Limits Management - quota checks performed automatically during install; if a limit is reached the stack pauses with a descriptive error. Review/request increases via Service Quotas Console (EC2, RDS, EKS node groups, ElastiCache, OpenSearch, NAT Gateways/VPC). Click 'Try Again' to resume. 4. License Management - managed through AWS Marketplace; license consumption tied to the AWS account; no license keys or manual activation; contact for BYOL/enterprise. 5. Maintenance - 5.1 Credential and Key rotation (customer responsible for rotating IAM credentials per AWS best practice; KMS CMKs provisioned automatically; recommend enabling automatic key rotation). 5.2 Fault Handling (errors show detailed message in Installation Wizard UI with 'Try Again'; post-deployment verify EC2/EKS/RDS/ElastiCache/OpenSearch; reboot/redeploy failed components; review VPC/DNS/IAM). 6. Software Patches and Upgrades - not via automated pipeline yet; customers notified of critical patches/new releases via AWS Marketplace product detail page (Release Notes/Usage Instructions). 7. Backup and recovery - no one-size-fits-all guide; review: RDS (automated backups on by default, point-in-time restore/snapshots), OpenSearch (manual/automated snapshots to S3), ElastiCache (snapshots), S3 (versioning/replication)." },
  { id: "faq-art-51000496239", categoryId: "faq-cat-getting-started", order: 14, title: "AWS DEPLOYMENT & SUPPORT GUIDE", slug: "aws-deployment-support-guide", summary: "The Personalisation Hub Platform installation takes around 1.2 hours: Stack creation (~4 min); Provide Platform Credentials (~2 min); Platform Installation (~1 hour - Master…", keywords: ["deployment","support","guide"], status: "published", bodyMd: "The Personalisation Hub Platform installation takes around 1.2 hours: Stack creation (~4 min); Provide Platform Credentials (~2 min); Platform Installation (~1 hour - Master Admin emailed on completion); DNS Set-Up (~2 min); Platform Set-Up/Customisation (~5 min). 1. Getting Support - Submit a ticket or email the support team; can assist with deployment errors, quota issues, configuration guidance. Include: AWS Account ID, CloudFormation Stack ID, Deployment Region, description of the issue (and steps to reproduce). 2. Standard Support Agreement (SLA) - Severity / Example / Initial Response / Diagnostic / Resolution / Service Target: P1 (Urgent) Platform API inaccessible / within 4 business hours / 6 business hours / 1 business day / 90%; P2 (High) Campaign/Playback Monitoring issues / 4 / 6 / 3 business days / 90%; P3 (Low) Table Loading Speed / 4 / 8 / 5 business days / 90%; P4 (Minor) HTML Formatting issue / 4 / 8 / 7 business days / 90%. 3. Enhanced Support/SLAs - for Enterprise clients, negotiated case by case." },
  { id: "faq-art-51000359321", categoryId: "faq-cat-store-sites", order: 0, title: "MOBILE SITES | Why Create a Mobile Site for your Stores?", slug: "mobile-sites-why-create-a-mobile-site-for-your-stores", summary: "The Platform automatically creates a Localised Mobile Site for every Connected Store.", keywords: ["mobile","sites","create","site","stores?","context"], status: "published", bodyMd: "The Platform automatically creates a Localised Mobile Site for every Connected Store. These Mobile Sites are context-aware and dynamically change depending on a user's location, and on which section of a store a customer is standing in (e.g. different experience between Football vs Rugby section). Each Mobile Site can adapt based on Context: Away from Store (info to get visitors to the front door); Connected Store State (info for current store visit, e.g. Join the Queue); Connected Display State (info related to current location within the store & engage with Campaigns on the Display); Store Open/Closed (adjust content based on opening hours). Why: support world-leading Retail CX; take ownership of the relationship from Local Search/Website to a Store Visit; provide contextual information & promotions based on context; open up engagement opportunities with Displays & Devices in-store (e.g. QR Control)." },
  { id: "faq-art-51000359492", categoryId: "faq-cat-store-sites", order: 1, title: "MOBILE SITES | Defining your Default Mobile Site", slug: "mobile-sites-defining-your-default-mobile-site", summary: "The Default Mobile Site Template is automatically assigned to all your Stores/Displays.", keywords: ["mobile","sites","defining","default","site","context"], status: "published", bodyMd: "The Default Mobile Site Template is automatically assigned to all your Stores/Displays. Update it to support the widest number of scenarios across your Stores. Add Menu Items that change depending on the Visitor's Current State (Away from Store, Checked In, Connected to & Engaging with a Display). You can also Only Show menu items when the Store is Currently Open (based on the Store's Opening Hours)." },
  { id: "faq-art-51000359556", categoryId: "faq-cat-store-sites", order: 2, title: "MOBILE SITES | Testing your Mobile Site", slug: "mobile-sites-testing-your-mobile-site", summary: "Once you've defined your Default Mobile Site, test it across different States.", keywords: ["mobile","sites","testing","site","context","aware"], status: "published", bodyMd: "Once you've defined your Default Mobile Site, test it across different States. Scanning a Store's QR Code opens the Mobile Site in an Away from Store State; Scanning a Display's QR Code opens it in a 'Connected Store' State as well as a 'Connected Display' State (if Triggered Campaigns have been defined for that Display)." },
  { id: "faq-art-51000359560", categoryId: "faq-cat-store-sites", order: 3, title: "MOBILE SITES | URLs Not Loading Correctly (Seeing a Blank Page)", slug: "mobile-sites-urls-not-loading-correctly-seeing-a-blank-page", summary: "When testing your Mobile Site URLs or Triggered Campaign URLs, some URLs may not show up as an iFrame within the Mobile Site (loads a blank page).", keywords: ["mobile","sites","urls","loading","correctly","seeing"], status: "published", bodyMd: "When testing your Mobile Site URLs or Triggered Campaign URLs, some URLs may not show up as an iFrame within the Mobile Site (loads a blank page). This happens because of restrictions within the referenced site's 'content-security-policy'. Immediate fix: select \"Open in New Tab\". Longer-term fix: raise a Change Request with your webmaster to update the site's content security policy for the affected URLs, so the referenced sites are approved to be loaded by your Platform's Domain. Example: content-security-policy: frame-ancestors 'self' *{PersonalisationHubPlatformDomain.com}; Recommendation: run the Platform on your Company's Primary domain (then the content-security-policy likely already supports this)." },
  { id: "faq-art-51000359588", categoryId: "faq-cat-store-sites", order: 4, title: "MOBILE SITES | Adding (Google Maps) Directions to your Mobile Site", slug: "mobile-sites-adding-google-maps-directions-to-your-mobile-site", summary: "Steps to provide Directions for Visitors to your respective Store (example uses Google Maps, but you could include URL/API details for any other service).", keywords: ["mobile","sites","adding","google","maps","directions"], status: "published", bodyMd: "Steps to provide Directions for Visitors to your respective Store (example uses Google Maps, but you could include URL/API details for any other service). The guide also covers how to use Tokens within any of your referenced URLs (within Mobile Site or Campaign's sections)." },
  { id: "faq-art-51000359590", categoryId: "faq-cat-store-sites", order: 5, title: "MOBILE SITES | Creating a Mobile Site Template for a Dedicated Concierge", slug: "mobile-sites-creating-a-mobile-site-template-for-a-dedicated-concierge", summary: "To set up a Display dedicated to allowing Visitors to 'Join the Queue' when they arrive in store, create a New Mobile Site Template that contains a Single Menu Item (\"Join the…", keywords: ["mobile","sites","creating","site","template","dedicated"], status: "published", bodyMd: "To set up a Display dedicated to allowing Visitors to 'Join the Queue' when they arrive in store, create a New Mobile Site Template that contains a Single Menu Item (\"Join the Queue\"). When only a Single Menu Item is defined, the Visitor is automatically redirected to the URL defined in that Menu Item when the template loads. This supports Auto URL Redirect when Visitors interact with specific Displays/Devices in-store. NOTE: Auto URL Redirect only works if No Campaigns are running on that specific Display/Device." },
  { id: "faq-art-51000359610", categoryId: "faq-cat-store-sites", order: 6, title: "MOBILE SITES | Assigning a Different Mobile Site Template to a Store OR Display/Zone", slug: "mobile-sites-assigning-a-different-mobile-site-template-to-a-store-or-display-zone", summary: "Control the Menu Options shown to Visitors by creating Different Mobile Site templates for Different Stores (e.g.", keywords: ["mobile","sites","assigning","different","site","template"], status: "published", bodyMd: "Control the Menu Options shown to Visitors by creating Different Mobile Site templates for Different Stores (e.g. a unique template for Stores in Shopping Malls). You can also control menu options based on a Visitor's Location within the Store (within specific Zones), by updating the Mobile Site Templates assigned to the Displays/Devices within specific Zones (e.g. \"Store Entrance\", \"Gaming Zone\", \"Football Zone\")." },
  { id: "faq-art-51000359638", categoryId: "faq-cat-store-sites", order: 7, title: "MOBILE SITES | Managing Which Campaigns Get Presented in the Campaign Carousel", slug: "mobile-sites-managing-which-campaigns-get-presented-in-the-campaign-carousel", summary: "When a Store Visitor scans the QR Code presented on a Display, they can Engage with & Control any Triggered Campaigns running on that Display.", keywords: ["mobile","sites","managing","which","campaigns","presented"], status: "published", bodyMd: "When a Store Visitor scans the QR Code presented on a Display, they can Engage with & Control any Triggered Campaigns running on that Display. Active Campaigns are presented within a CAMPAIGN CAROUSEL above your Mobile Site Menus. From the CAMPAIGNS section you can Activate/Deactivate Campaigns shown in this Campaign Carousel." },
  { id: "faq-art-51000359675", categoryId: "faq-cat-store-sites", order: 8, title: "MOBILE SITES | Controlling the Order in Which Campaigns Get Presented", slug: "mobile-sites-controlling-the-order-in-which-campaigns-get-presented", summary: "Once you've set up all your Campaigns, control the Order in which they are presented on the Mobile Site within the Campaign Carousel.", keywords: ["mobile","sites","controlling","order","which","campaigns"], status: "published", bodyMd: "Once you've set up all your Campaigns, control the Order in which they are presented on the Mobile Site within the Campaign Carousel. Follow the steps to update the Campaign Prioritisation for a specific Display-Type." },
  { id: "faq-art-51000359680", categoryId: "faq-cat-store-sites", order: 9, title: "MOBILE SITES | Creating a CTA for On-Rotation Campaigns", slug: "mobile-sites-creating-a-cta-for-on-rotation-campaigns", summary: "With most Digital Signage Solutions, Brands/Advertisers must include QR Codes in the Creative and Visitors wait for the Campaign to play again to scan in time.", keywords: ["mobile","sites","creating","rotation","campaigns","context"], status: "published", bodyMd: "With most Digital Signage Solutions, Brands/Advertisers must include QR Codes in the Creative and Visitors wait for the Campaign to play again to scan in time. Personalisation Hub shows a dedicated QR Code on each Display; when a Visitor scans it they can browse through all the (On-Rotation) Campaigns running on that specific Display. Steps cover uploading a Campaign Banner & creating a Call To Action for your On-Rotation Campaigns." },
  { id: "faq-art-51000363519", categoryId: "faq-cat-store-sites", order: 10, title: "MOBILE SITES | Personalise a Visitor's Store Experience", slug: "mobile-sites-personalise-a-visitor-s-store-experience", summary: "Further Personalise a Visitor's Store Experience based on the section of the Store they are in by creating different Mobile Site Templates for different Zones.", keywords: ["mobile","sites","personalise","visitor","experience","context"], status: "published", bodyMd: "Further Personalise a Visitor's Store Experience based on the section of the Store they are in by creating different Mobile Site Templates for different Zones. Once a Visitor scans the QR Code on a Display in a specific Zone, the dedicated Mobile Site template is used. Steps are the same as creating a dedicated Concierge Kiosk Experience but with more Menu Items added. Also covers Triggered Campaigns (control Campaign/Video Playback on a Display), CTAs/Banners for On-Rotation Campaigns, and Manually Adding a Campaign/Banner to the Campaign Carousel not associated with a Campaign Playing on that Display." },
  { id: "faq-art-51000290787", categoryId: "faq-cat-retail-data-management", order: 0, title: "HQ ADMIN | Introduction to Stores / Branches", slug: "hq-admin-introduction-to-stores-branches", summary: "Uplifting NPS in Retail starts with accurate Retail Data.", keywords: ["admin","introduction","branches","retail","data","management"], status: "published", bodyMd: "Uplifting NPS in Retail starts with accurate Retail Data. If a Customer checks a Store's Opening Hours and arrives to find it Closed, no level of Localisation & Personalisation will save the situation. The Platform ensures clients establish a single source of truth for Retail Data, continually validated by Front-Line staff, synchronised across External Platforms (e.g. Google Business Profiles), and exposed through Enterprise-Grade APIs. Location/Retail Data managed through the Platform: Store Codes (Unique ID to sync retail data between systems, e.g. GBP & AEM); Store Name (user facing); State/Address Data (GBP address data to localise campaigns); Opening Hour Data (central source of truth, validated by front-line staff); # of Connected Displays & Display/Network Status (real-time monitoring); Store Segments (used for Geo Targeting; can be managed by Store Manager via Retail Admin Tablet); Fixed Store Segments (only used by/visible to Headquarters, not visible to Local Store Managers)." },
  { id: "faq-art-51000360500", categoryId: "faq-cat-retail-data-management", order: 1, title: "STORE DATA | View a Store's Network / Display Status", slug: "store-data-view-a-store-s-network-display-status", summary: "Strongly recommend following these steps Daily (Every Morning) to identify and resolve Store-Network/Display issues before trading starts.", keywords: ["data","view","network","display","status","retail"], status: "published", bodyMd: "Strongly recommend following these steps Daily (Every Morning) to identify and resolve Store-Network/Display issues before trading starts. The Platform monitors all Connected Displays & Devices. If all Devices go Offline in a Store, the Store's status turns RED (a sign the Store may not be able to Trade; if no longer operating, delete it). If one or more (but not all) Devices go Offline, the Store status turns ORANGE (impacts Personalised Experiences on associated Displays). Steps cover checking Store Status for all your Stores." },
  { id: "faq-art-51000360360", categoryId: "faq-cat-retail-data-management", order: 2, title: "STORE DATA | Update a Store Code", slug: "store-data-update-a-store-code", summary: "If you are using AEM as your CMS, first update the Store Code in AEM (STEP 1); once updated and Published, update the Store Code in Personalisation Hub (STEP 2).", keywords: ["data","code","retail","management"], status: "published", bodyMd: "If you are using AEM as your CMS, first update the Store Code in AEM (STEP 1); once updated and Published, update the Store Code in Personalisation Hub (STEP 2). [NOTE: AEM reference - now superseded by built-in Digital Signage.]" },
  { id: "faq-art-51000360361", categoryId: "faq-cat-retail-data-management", order: 3, title: "STORE DATA | Update a Store's Name", slug: "store-data-update-a-store-s-name", summary: "To update a Store's Name, follow the steps provided.", keywords: ["data","name","retail","management"], status: "published", bodyMd: "To update a Store's Name, follow the steps provided." },
  { id: "faq-art-51000360461", categoryId: "faq-cat-retail-data-management", order: 4, title: "STORE DATA | Delete a Store/Location", slug: "store-data-delete-a-store-location", summary: "If you are using AEM as your CMS, first Unpublish and Delete the Store/Location from AEM (STEP 1), then Delete the Store from Personalisation Hub (STEP 2).", keywords: ["data","delete","location","retail","management"], status: "published", bodyMd: "If you are using AEM as your CMS, first Unpublish and Delete the Store/Location from AEM (STEP 1), then Delete the Store from Personalisation Hub (STEP 2). [NOTE: AEM reference - now superseded by built-in Digital Signage.]" },
  { id: "faq-art-51000360495", categoryId: "faq-cat-retail-data-management", order: 5, title: "STORE DATA | Add / Update a Store's Address", slug: "store-data-add-update-a-store-s-address", summary: "NOTE: You need your Organisation's Google Maps/Places API Key added to the Platform before you can Add Location Addresses/Details.", keywords: ["data","address","retail","management"], status: "published", bodyMd: "NOTE: You need your Organisation's Google Maps/Places API Key added to the Platform before you can Add Location Addresses/Details. Add a Location's address from the Store's Details Page. When an Existing Store has Opening Hours defined, the Opening Hours are also added (along with the address). Steps provided." },
  { id: "faq-art-51000360505", categoryId: "faq-cat-retail-data-management", order: 6, title: "STAFF TABLET | Validate Store's Details / Address", slug: "staff-tablet-validate-store-s-details-address", summary: "Ensuring Customers always have accurate Data is critical.", keywords: ["staff","tablet","validate","details","address","retail"], status: "published", bodyMd: "Ensuring Customers always have accurate Data is critical. Decentralising Data Validation/Control to Store Staff/Managers keeps data accurate. Steps for how Store Staff can check/validate their Store's Details via the Staff Tablet interface." },
  { id: "faq-art-51000360506", categoryId: "faq-cat-retail-data-management", order: 7, title: "STAFF TABLET | Update Store's Opening Hours", slug: "staff-tablet-update-store-s-opening-hours", summary: "Steps for how Store Staff can check/validate their Store's Opening Hours via the Staff Tablet interface.", keywords: ["staff","tablet","opening","hours","retail","data"], status: "published", bodyMd: "Steps for how Store Staff can check/validate their Store's Opening Hours via the Staff Tablet interface." },
  { id: "faq-art-51000360508", categoryId: "faq-cat-retail-data-management", order: 8, title: "STAFF TABLET | Update a Store's (Variable) Segment(s)", slug: "staff-tablet-update-a-store-s-variable-segment-s", summary: "CAMPAIGN LOCALISATION - Store Managers can be empowered to drive a certain level of Localisation within their Store.", keywords: ["staff","tablet","variable","segment","retail","data"], status: "published", bodyMd: "CAMPAIGN LOCALISATION - Store Managers can be empowered to drive a certain level of Localisation within their Store. Variable Store Segments can be created/authored (see Localisation Section). Once set up, Store Managers can control their respective Variable Store Segments. Steps cover how they update/change these." },
  { id: "faq-art-51000290789", categoryId: "faq-cat-display-device-management", order: 0, title: "HQ ADMIN | Introduction to Displays & Devices", slug: "hq-admin-introduction-to-displays-devices", summary: "Differentiation within Retail happens through Experiences.", keywords: ["admin","introduction","displays","devices","display","device"], status: "published", bodyMd: "Differentiation within Retail happens through Experiences. As these become more connected, the number of Devices in Retail multiplies. Differentiated Experiences can only be supported when Displays & Devices are Online & Playing the Correct Campaigns/Experiences. The Platform allows Enterprise Clients to manage their Retail Display Network & track that the correct Campaigns are playing in the correct places. Supported Display/Device data: Device/Display Status (live Online/Offline); Display Name (unique per store, e.g. Sports Zone, Store Entrance); Display Type (clear naming convention for campaign management at scale); Screen Orientation (control orientation, typically for Portrait Displays at 90/270); Display Tags (used for Geo Targeting at a Display level); Active Playlist/Channel (determines campaigns/experiences supported); Active Campaigns (Triggered Campaigns activatable by Retail Staff via Staff Tablets); Asset ID; Public IP Address; Device Serial Number; Unique Device ID; Display QR-Code (connect to & control this Display; continually changes - click Refresh QR Code); Campaign Playback Tab (near real-time summary of Campaigns playing and Triggered Campaigns interacted with via QR Control, Dialogflow or Staff Tablet); Device Log Tab (display/device specific events - Offline, New Device Added, Screen Orientation changed)." },
  { id: "faq-art-51000290858", categoryId: "faq-cat-display-device-management", order: 1, title: "Offline Device Notifications", slug: "offline-device-notifications", summary: "The Offline Device Notification feature allows clients to create Email Notifications for any Displays/Devices connected to the Platform.", keywords: ["offline","device","notifications","display","management"], status: "draft", bodyMd: "The Offline Device Notification feature allows clients to create Email Notifications for any Displays/Devices connected to the Platform. If a Display/Device is Offline for the pre-defined period, an Email Notification is sent. Navigate to the Displays & Devices section. For ALL DISPLAYS & DEVICES: at the top of the table select 'Offline Device Notification' > Create New Notification > enter email addresses (press Return after each) > select how long the device should be Offline before triggering > select frequency (Daily, Weekly, Fortnightly, Monthly) > leave Enabled toggle ON to start immediately > Save. For SELECTED DISPLAYS & DEVICES: tick all desired Displays/Devices > Create Offline Device Notification > enter email addresses > select offline duration > select frequency > leave Enabled ON > Save." },
  { id: "faq-art-51000360571", categoryId: "faq-cat-display-device-management", order: 2, title: "DISPLAYS | View Display & Device's Status (incl time Offline)", slug: "displays-view-display-device-s-status-incl-time-offline", summary: "Strongly recommend reviewing which Displays & Devices are Offline every morning (impacts ability to support Personalised Experiences and associated revenue).", keywords: ["displays","view","display","device","status","incl"], status: "published", bodyMd: "Strongly recommend reviewing which Displays & Devices are Offline every morning (impacts ability to support Personalised Experiences and associated revenue). From HQ Admin you can track the length of time specific Displays & Devices have been Offline (may highlight H/W or OS issues). Information available on a Display Detail's page for troubleshooting: Active Channel; Asset ID; Public IP Address; AEM Display Path (location of the Device/Display within AEM - for troubleshooting in AEM) [NOTE: AEM reference - now superseded by built-in Digital Signage]; Device Serial Number; Unique Device ID; Campaign Playback Tab; Device Log Tab." },
  { id: "faq-art-51000360574", categoryId: "faq-cat-display-device-management", order: 3, title: "DISPLAYS | Identify Campaign Playback Issues on Displays", slug: "displays-identify-campaign-playback-issues-on-displays", summary: "Strongly recommend reviewing and resolving any Campaign Playback Issues every morning before stores open (impacts Personalised Experiences and associated revenue).", keywords: ["displays","identify","campaign","playback","issues","display"], status: "published", bodyMd: "Strongly recommend reviewing and resolving any Campaign Playback Issues every morning before stores open (impacts Personalised Experiences and associated revenue). Steps to quickly identify Campaign Playback Issues are provided." },
  { id: "faq-art-51000360577", categoryId: "faq-cat-display-device-management", order: 4, title: "DISPLAYS | View a Display / Device's Log (History)", slug: "displays-view-a-display-device-s-log-history", summary: "When running hundreds/thousands of Displays & Devices, it is critical to keep track of Issues/Changes.", keywords: ["displays","view","display","device","history","management"], status: "published", bodyMd: "When running hundreds/thousands of Displays & Devices, it is critical to keep track of Issues/Changes. The Platform maintains a Device Log for every connected Device recording all changes. Steps to access a specific Device's Log are provided." },
  { id: "faq-art-51000360693", categoryId: "faq-cat-display-device-management", order: 5, title: "DISPLAYS | Update a Display's Name (HQ Admin & Staff Tablet)", slug: "displays-update-a-display-s-name-hq-admin-staff-tablet", summary: "The Display Name is presented to Staff when Visitors Interact with Displays in Store, so it should accurately reflect the Display's position within the Store.", keywords: ["displays","display","name","admin","staff","tablet"], status: "published", bodyMd: "The Display Name is presented to Staff when Visitors Interact with Displays in Store, so it should accurately reflect the Display's position within the Store. Steps cover: 1. HQ Admin - Update a Display's Name; 2. Staff Tablet - Update a Display's Name." },
  { id: "faq-art-51000363266", categoryId: "faq-cat-display-device-management", order: 6, title: "DISPLAYS | Update a Display's Image / Icon", slug: "displays-update-a-display-s-image-icon", summary: "To update the Image/Icon presented next to a specific Store's Displays via the Display's Details Page.", keywords: ["displays","display","image","icon","device","management"], status: "published", bodyMd: "To update the Image/Icon presented next to a specific Store's Displays via the Display's Details Page. Steps provided." },
  { id: "faq-art-51000360730", categoryId: "faq-cat-display-device-management", order: 7, title: "DISPLAYS | Update Display's Screen Orientation (HQ Admin & Staff Tablet)", slug: "displays-update-display-s-screen-orientation-hq-admin-staff-tablet", summary: "Allowing Staff (especially Retail Staff) to immediately resolve Screen Orientation issues removes unnecessary overhead.", keywords: ["displays","display","screen","orientation","admin","staff"], status: "published", bodyMd: "Allowing Staff (especially Retail Staff) to immediately resolve Screen Orientation issues removes unnecessary overhead. Steps cover: 1. HQ Admin - Update Display's Screen Orientation; 2. Staff Tablet - Update Display's Screen Orientation." },
  { id: "faq-art-51000360735", categoryId: "faq-cat-display-device-management", order: 8, title: "DISPLAYS | View / Filter by Channel Playing on Displays", slug: "displays-view-filter-by-channel-playing-on-displays", summary: "To check which Channel(s) are Actively Playing on which Displays (for troubleshooting or ensuring correct Campaigns play on correct Displays/Display-Types).", keywords: ["displays","view","filter","channel","playing","display"], status: "published", bodyMd: "To check which Channel(s) are Actively Playing on which Displays (for troubleshooting or ensuring correct Campaigns play on correct Displays/Display-Types). Steps provided." },
  { id: "faq-art-51000360736", categoryId: "faq-cat-display-device-management", order: 9, title: "DISPLAYS | View Campaign Playback Audit for Displays", slug: "displays-view-campaign-playback-audit-for-displays", summary: "The Platform continually monitors exactly which campaigns are playing across your Retail Display Network.", keywords: ["displays","view","campaign","playback","audit","display"], status: "published", bodyMd: "The Platform continually monitors exactly which campaigns are playing across your Retail Display Network. Check a summary of Playback Audit for the past 24 hours from the Displays & Devices Table, or access the 'Campaign Playback' Tab for a detailed view at an individual Display level. Steps provided." },
  { id: "faq-art-51000360796", categoryId: "faq-cat-display-device-management", order: 10, title: "DISPLAYS | Access all the Identifiers for a Display", slug: "displays-access-all-the-identifiers-for-a-display", summary: "The Platform centralises all the Identifiers that may be required for troubleshooting issues in downstream systems.", keywords: ["displays","access","identifiers","display","device","management"], status: "published", bodyMd: "The Platform centralises all the Identifiers that may be required for troubleshooting issues in downstream systems. Steps to access all the Device/Display Identifiers provided." },
  { id: "faq-art-51000360798", categoryId: "faq-cat-display-device-management", order: 11, title: "ACTIVE INTEGRATIONS | Enable QR-Control on a Display", slug: "active-integrations-enable-qr-control-on-a-display", summary: "NOTE: Triggered Campaigns must be set up to support this feature (see 'Personalisation' section).", keywords: ["active","integrations","enable","control","display","device"], status: "published", bodyMd: "NOTE: Triggered Campaigns must be set up to support this feature (see 'Personalisation' section). You can allow Store Visitors to engage with Displays using their own mobile devices via QR-Control: scan a QR-Code presented on a Display and the mobile device acts as a remote control to that Display, with Experiences synchronised between the Visitor's Mobile and the Display. Once Triggered Campaigns are set up, follow the steps to enable QR Control on an individual Display." },
  { id: "faq-art-51000360815", categoryId: "faq-cat-display-device-management", order: 12, title: "ACTIVE INTEGRATIONS | Enable Chatbot Interactions on a Display or via the Mobile Site", slug: "active-integrations-enable-chatbot-interactions-on-a-display-or-via-the-mobile-site", summary: "NOTE: Triggered Campaigns must be set up and the Platform integrated with Dialogflow to support ChatBot interactions on/with a Display (raise a ticket for setup support).", keywords: ["active","integrations","enable","chatbot","interactions","display"], status: "published", bodyMd: "NOTE: Triggered Campaigns must be set up and the Platform integrated with Dialogflow to support ChatBot interactions on/with a Display (raise a ticket for setup support). Once connected to Dialogflow, Brands can synchronise Experiences on Displays based on the Conversational Intent with a Visitor. Triggered Campaigns are mapped to specific Synonyms/Utterances; once matched, Brands can Trigger Campaign Playback on the Connected Display. Steps for an individual Display provided." },
  { id: "faq-art-51000326290", categoryId: "faq-cat-troubleshooting", order: 0, title: "Unable to Access Platform - Seeing Access Denied Error Message", slug: "unable-to-access-platform-seeing-access-denied-error-message", summary: "For Security reasons, your Organisation may have white-listed the IP addresses allowed to access your instance.", keywords: ["unable","access","platform","seeing","denied","error"], status: "published", bodyMd: "For Security reasons, your Organisation may have white-listed the IP addresses allowed to access your instance. If your IP is not on the list: Step 1 - ensure you're accessing from an Approved (White Listed) IP Address. Step 2 - check the Error. Error 1 (blocked by CDN, e.g. Akamai or CloudFront) - copy the Reference # and send to your CDN team to identify why you're blocked (e.g. Geo-Fencing rules). Error 2 (blocked by the Platform) - Google \"What's My IP Address\", copy/paste and send to your Platform Admin to white-list your IP within the Platform." },
  { id: "faq-art-51000363270", categoryId: "faq-cat-troubleshooting", order: 1, title: "Unable to Login to the Platform", slug: "unable-to-login-to-the-platform", summary: "Steps: 1 - ensure you're using the correct email address registered to use the Platform.", keywords: ["unable","login","platform","troubleshooting"], status: "published", bodyMd: "Steps: 1 - ensure you're using the correct email address registered to use the Platform. 2 - ensure the correct Password (reset if unsure). 3 - clear your browser's cache and try again. 4 - try logging in in 'Incognito Mode'. 5 - if still unable, raise a Support Ticket with the team." },
  { id: "faq-art-51000483994", categoryId: "faq-cat-troubleshooting", order: 2, title: "SMS SENDING ISSUES | SMS Messages not sent or sent as UNVERIFIED", slug: "sms-sending-issues-sms-messages-not-sent-or-sent-as-unverified", summary: "To send SMS messages from AWS, ensure your AWS environment is out of Sandbox Mode and you have approval to use the SMS Sender ID defined within COMPANY SETTINGS > PLATFORM SET-UP.", keywords: ["sending","issues","messages","sent","unverified","troubleshooting"], status: "published", bodyMd: "To send SMS messages from AWS, ensure your AWS environment is out of Sandbox Mode and you have approval to use the SMS Sender ID defined within COMPANY SETTINGS > PLATFORM SET-UP. If you are not receiving SMS messages, or messages are delivered as UNVERIFIED Sender, follow the steps in the AWS Support article to register your desired SMS Sender ID." },
  { id: "faq-art-51000483636", categoryId: "faq-cat-appointment-bookings", order: 0, title: "SET UP | Enable Appointment Bookings", slug: "set-up-enable-appointment-bookings", summary: "Allow customers to book an appointment with a store at a time that works for them, without waiting in the store's virtual queue.", keywords: ["enable","appointment","bookings","appointments"], status: "published", bodyMd: "Allow customers to book an appointment with a store at a time that works for them, without waiting in the store's virtual queue. To set this up: 1. Enable Appointments within the Platform; 2. Enable Appointments for a specific Store; 3. Check/Update your Reason for Visit data; 4. Managing Calendar Blockings & Public Holidays." },
  { id: "faq-art-51000491524", categoryId: "faq-cat-digital-signage", order: 0, title: "SET-UP | Enabling Digital Signage", slug: "set-up-enabling-digital-signage", summary: "[STATUS: DRAFT] Digital Signage in Personalisation Hub delivers dynamic, context-aware content across in-store displays.", keywords: ["enabling","digital","signage"], status: "draft", bodyMd: "[STATUS: DRAFT] Digital Signage in Personalisation Hub delivers dynamic, context-aware content across in-store displays. Before You Begin: Administrator access; Display Management permissions; store list/display locations ready. Step 1 - Navigate to Display Management (Digital Signage > Displays). Step 2 - Enable the Digital Signage Module (Settings gear > Modules > toggle Digital Signage to Enabled > Save Settings). Step 3 - Confirm Connection Status (should show Active/green; if inactive verify firewall allows outbound traffic to Personalisation Hub endpoints). Step 4 - Review Default Display Types (Digital Signage > Display Types; default Landscape or Portrait). Step 5 - Verify Device Access (each display requires a registration code; manage in Displays > Register Device). Next Steps: Registering a New Digital Signage Device; Create a New Display Type and Playlist." },
  { id: "faq-art-51000491526", categoryId: "faq-cat-digital-signage", order: 1, title: "SET-UP | Registering a New Digital Signage Device/Display", slug: "set-up-registering-a-new-digital-signage-device-display", summary: "After enabling Digital Signage, register each display/device so it can receive campaigns.", keywords: ["registering","digital","signage","device","display"], status: "published", bodyMd: "After enabling Digital Signage, register each display/device so it can receive campaigns. Before You Begin: Digital Signage enabled; device management (MDM/CDM) configured to launch the PWA Kiosk Player, or PWA player URL ready. Step 1 - Point the Device to the Platform (drag/drop the new device into the correct organisational unit and assign the PWA Player URL, or manually enter the PWA URL into the device's browser; power on; device shows a registration code). Step 2 - Open the Displays & Devices Panel (Digital Signage > Displays & Devices > Unassigned Devices tab). Step 3 - Register the Device (match by Asset ID or registration code > Register Device > enter Device Name, choose Store/Location, select Display Type > Register Device to confirm). Next Steps: Register a Display/Device; Add a Campaign to Play on a Digital Signage Display; Scheduling a Campaign." },
  { id: "faq-art-51000506169", categoryId: "faq-cat-digital-signage", order: 2, title: "USE | Create a New Display Type and Playlist", slug: "use-create-a-new-display-type-and-playlist", summary: "Creating custom Display Types lets you tailor signage to different screen orientations and resolutions.", keywords: ["create","display","type","playlist","digital","signage"], status: "published", bodyMd: "Creating custom Display Types lets you tailor signage to different screen orientations and resolutions. Each Display Type has an associated default Playlist. Before You Begin: Digital Signage enabled; know resolution/orientation (e.g. 1920x1080 landscape, 1080x1920 portrait); admin access. Step 1 - Navigate to Display Types (Digital Signage > Display Types). Step 2 - Add a New Display Type (Add Display Type > enter Name e.g. \"Entrance-Landscape\" > set Resolution Width x Height > optional Description > Save Changes; a default Playlist with the same name is created automatically). Step 3 - Review and Edit the Playlist (organise campaigns that should play by default; accessible later from Digital Signage > Playlists). Next Steps: Add a Campaign to Play on a Digital Signage Display; Scheduling a Campaign." },
  { id: "faq-art-51000491547", categoryId: "faq-cat-digital-signage", order: 3, title: "USE | Add a Campaign to Play on a Digital Signage Display", slug: "use-add-a-campaign-to-play-on-a-digital-signage-display", summary: "Campaigns are the messages and media that play on your Displays.", keywords: ["campaign","play","digital","signage","display"], status: "published", bodyMd: "Campaigns are the messages and media that play on your Displays. Before You Begin: assets correctly formatted for the Display Types; at least one Display and Display Type registered; permissions to create campaigns in HQ Admin. Step 1 - Go to Campaigns (HQ Admin > Campaigns > Add New Campaign). Step 2 - Enter Campaign Details (Campaign Name, description; enable Touchpoints - toggle Digital Signage ON - and select Playlist(s); proceed to Audience Targeting and Scheduling tabs; select Creative tab & Upload assets for each enabled touchpoint/playlist). Step 3 - Activate the Campaign (enable the Activate toggle, top right). Next Steps: Scheduling a Campaign; Targeting a Campaign." },
  { id: "faq-art-51000500898", categoryId: "faq-cat-digital-signage", order: 4, title: "USE | Scheduling a Campaign", slug: "use-scheduling-a-campaign", summary: "Scheduling controls exactly when a campaign appears on your digital displays (multiple schedules for different times/days, e.g.", keywords: ["scheduling","campaign","digital","signage"], status: "published", bodyMd: "Scheduling controls exactly when a campaign appears on your digital displays (multiple schedules for different times/days, e.g. lunch promos during lunchtime). Before You Begin: campaign created with basic details; timezone and business hours confirmed; permissions. Step 1 - Open the Scheduling Tab (from Campaigns, open the campaign > Scheduling tab). Step 2 - Add a New Schedule (Add New Schedule > descriptive Schedule Name e.g. \"Lunch Menu weekdays\"). Step 3 - Configure Schedule Details (Start/End Date & Time; Mode - All Day, Specific Time Range, When Store OPEN, When Store CLOSED; set daily start/end times e.g. 12:00 PM-2:00 PM; recurrence rules e.g. weekdays). Step 4 - Assign Displays or Display Types (choose Display Types, Stores, or individual Displays). Step 5 - Save and Repeat (create additional schedules e.g. breakfast and dinner). Next Steps: Targeting a Campaign; Targeting using Zones; Targeting at a Specific Display Level." },
  { id: "faq-art-51000500901", categoryId: "faq-cat-digital-signage", order: 5, title: "USE | Targeting a Campaign", slug: "use-targeting-a-campaign", summary: "Targeting controls where and to whom your campaign plays by defining audience and location rules.", keywords: ["targeting","campaign","digital","signage"], status: "published", bodyMd: "Targeting controls where and to whom your campaign plays by defining audience and location rules. Before You Begin: campaign created with schedules; Store Segments/Display Tags/Customer Segments defined (under Company Settings); permissions. Step 1 - Open the Audience Targeting Tab. Step 2 - Add a Targeting Rule (Add Targeting Rule > choose Targeting Variable e.g. Store Segment, Display Tag, Customer Segment, Zone; select Operator e.g. includes selected, equals, does not include; select Values). Step 3 - Combine Multiple Rules (Add another rule; combined with AND/OR logic). Step 4 - Review and Save. Next Steps: Targeting using Zones; Targeting at a Specific Display Level; Scheduling a Campaign." },
  { id: "faq-art-51000360858", categoryId: "faq-cat-digital-signage", order: 6, title: "USE | Targeting at a Store / Location Level using Store Segments", slug: "use-targeting-at-a-store-location-level-using-store-segments", summary: "Group stores into segments and deliver content to those segments only (organise by demographic, region, traffic, etc).", keywords: ["targeting","location","level","segments","digital","signage"], status: "published", bodyMd: "Group stores into segments and deliver content to those segments only (organise by demographic, region, traffic, etc). Before You Begin: localisation strategy defined; Store Segments created in Company Settings > Retail Settings > Store Segments; permissions; campaign with details/schedules. Step 1 - Create or Edit Store Segments (Add New Store Segment; choose Fixed (HQ only) or Variable (store managers can enable/disable); Name e.g. \"Metropolitan Stores\"; Save). Step 2 - Assign Segments to Stores (Stores/Branches > select store > Store Segments section > enable/disable Variable segments; fixed segments auto-applied by HQ; Save). Step 3 - Target a Campaign by Store Segment (Audience Targeting tab > Add Targeting Rule > Targeting Variable = Store Segment > operator includes selected > select segments > Save). Next Steps: Targeting at a Specific Display Level; Scheduling a Campaign." },
  { id: "faq-art-51000360912", categoryId: "faq-cat-digital-signage", order: 7, title: "USE | Targeting at a specific Display Level", slug: "use-targeting-at-a-specific-display-level", summary: "Deliver content to individual screens based on location or purpose using Display Tags.", keywords: ["targeting","specific","display","level","digital","signage"], status: "published", bodyMd: "Deliver content to individual screens based on location or purpose using Display Tags. Before You Begin: Display Tags created in HQ Admin; displays registered; campaign with details/schedules. Step 1 - Create Display Tags (Company Settings > Retail Settings > Display Tags > Add New Display Tag > name e.g. \"Food Court\" > Save). Step 2 - Assign Display Tags to Displays (Digital Signage > Displays & Devices > open the display > Display Tags field > select tags > Save). Step 3 - Target a Campaign by Display Tag (Audience Targeting tab > Add Targeting Rule > Targeting Variable = Display Tag > operator includes selected > select tags > Save). Next Steps: Targeting a Campaign; Scheduling a Campaign." },
  { id: "faq-art-51000506170", categoryId: "faq-cat-digital-signage", order: 8, title: "USE | Register a Display / Device", slug: "use-register-a-display-device", summary: "Registering a new display/device adds it to your Digital Signage network so it can receive content.", keywords: ["register","display","device","digital","signage"], status: "published", bodyMd: "Registering a new display/device adds it to your Digital Signage network so it can receive content. Before You Begin: Asset ID or serial number; permissions; store and display type created. Step 1 - Go to Unassigned Devices (Displays & Devices > Unassigned Devices). Step 2 - Complete the Registration Form (next to the device click Register > enter Display Name (Asset ID default, changeable) > select store > choose display type e.g. \"Shop-Front-Landscape\" > Save). Device now appears under Assigned Devices and can receive scheduled campaigns. Next Steps: Create a New Display Type and Playlist; Add a Campaign to Play on a Digital Signage Display." },
  { id: "faq-art-51000507772", categoryId: "faq-cat-digital-signage", order: 9, title: "Localise Campaigns | Adding Store Segments", slug: "localise-campaigns-adding-store-segments", summary: "After defining your localisation strategy, add store segments to Personalisation Hub and launch campaigns targeted at those segments to control which campaigns play in each…", keywords: ["localise","campaigns","adding","segments","localisation","targeting"], status: "published", bodyMd: "After defining your localisation strategy, add store segments to Personalisation Hub and launch campaigns targeted at those segments to control which campaigns play in each store/location. Types of Store Segments: Fixed (controlled by and only visible to Headquarters); Variable (controlled by Retail Store Managers and Headquarters, visible to all staff). Step-by-Step: Login to HQ Admin > Company Settings > Store Segments > add desired Variable & Fixed Store Segments > Stores & Branches > select store(s) > add the Variable/Fixed store segments to each store > Save Changes. Add Targeting Rules: open the Campaign > Audience Targeting tab > [+ Add New 'AND' Condition] > select 'Store / Location Data' > select Variable/Fixed Store Segments > operator (e.g. 'includes selected') > add segments > Save Changes. NOTE: Use 'Store Segments (Consolidated)' to add segments that could be either fixed or variable." },
  { id: "faq-art-51000508013", categoryId: "faq-cat-digital-signage", order: 10, title: "Localise Campaigns | Adding Display Tags", slug: "localise-campaigns-adding-display-tags", summary: "To target campaigns at a display level: first define a clear & consistent display-type naming convention (e.g.", keywords: ["localise","campaigns","adding","display","tags","localisation"], status: "published", bodyMd: "To target campaigns at a display level: first define a clear & consistent display-type naming convention (e.g. store-entrance-portrait-left; store-entrance-portrait-right). Then use display tags to refine targeting (e.g. overlooked by food hall, in high-traffic area, 24 hour passer-by traffic). Step-by-Step: Login to HQ Admin > Company Settings > Display Tags > add desired Display Tags > Displays & Devices > select Display(s) > assign Display Tags > Save Changes. Add Targeting Rules: open the Campaign > Audience Targeting tab > [+ Add New 'AND' Condition] > 'Store / Location Data' > Display Tag(s) > operator (e.g. 'includes selected') > add display tag(s) > Save Changes." },
  { id: "faq-art-51000508014", categoryId: "faq-cat-digital-signage", order: 11, title: "Localise Campaigns | Based on Store Visitors Reason for Visit", slug: "localise-campaigns-based-on-store-visitors-reason-for-visit", summary: "If using Virtual Queue Management, target campaigns based on the reason customers are waiting for assistance in-store (aggregate basis; triggered based on the percentage…", keywords: ["localise","campaigns","based","visitors","reason","visit"], status: "published", bodyMd: "If using Virtual Queue Management, target campaigns based on the reason customers are waiting for assistance in-store (aggregate basis; triggered based on the percentage defined in the audience targeting rule). Example: a bank, when >50% of customers are waiting for a home-loan, ensures all campaigns in that branch promote latest home-loan offers. NOTE: you can add multiple display-type playlists to a single campaign so creative plays on all displays simultaneously within the store. Step-by-Step: open the Campaign > Audience Targeting tab > [+ Add New 'AND' Condition] > 'Queueing / Aggregate Visitor Data' > Reason for Visit (Aggregate) > operator (e.g. 'greater than') > add percentage (e.g. 50%) > Save Changes." },
  { id: "faq-art-51000508017", categoryId: "faq-cat-digital-signage", order: 12, title: "Localise Campaigns | Based on Staff Member's Skills that are currently On-Shift", slug: "localise-campaigns-based-on-staff-member-s-skills-that-are-currently-on-shift", summary: "If stores use the staff-tablet/retail-admin interface, target campaigns based on languages/skills of staff on-shift (status 'Available').", keywords: ["localise","campaigns","based","staff","member","skills"], status: "published", bodyMd: "If stores use the staff-tablet/retail-admin interface, target campaigns based on languages/skills of staff on-shift (status 'Available'). Example: stores in multicultural neighbourhoods can promote that staff currently on-shift speak specific languages (e.g. Chinese). NOTE: Staff must define the Languages they speak within their staff profile. Step-by-Step: open the Campaign > Audience Targeting tab > [+ Add New 'AND' Condition] > 'Store / Location Data' > 'Languages Spoken by Staff' > operator (e.g. 'includes selected') > select staff language(s) > Save Changes." },
  { id: "faq-art-51000508033", categoryId: "faq-cat-digital-signage", order: 13, title: "Localise Campaigns | Based on Passer-by Audience's Gender/Age (using Computer Vision running @ the Edge)", slug: "localise-campaigns-based-on-passer-by-audience-s-gender-age-using-computer-vision-running-the-edge", summary: "Target campaigns based on the gender/age of customers walking past your stores/displays using the platform's built-in computer vision capability.", keywords: ["localise","campaigns","based","passer","audience","gender"], status: "published", bodyMd: "Target campaigns based on the gender/age of customers walking past your stores/displays using the platform's built-in computer vision capability. Vision requires a webcam connected to the display; the computer vision model runs at the Edge (no sensitive data leaves the local device/player). The platform can also run custom computer vision models at the Edge (complexity hardware dependent; raise a support ticket). Step-by-Step: open the Campaign > Audience Targeting tab > [+ Add New 'AND' Condition] > 'Visitor / Customer Data' > 'Gender' > 'equal' > add Gender (male/female) > Save Changes. Then enable Vision: Displays & Devices > click the Display/Device > 'Enabled Features' tab > tick 'Enable Vision/AI' > Save Changes." },
  { id: "faq-art-51000359022", categoryId: "faq-cat-digital-signage", order: 14, title: "PERSONALISATION | What are Triggered Campaigns?", slug: "personalisation-what-are-triggered-campaigns", summary: "Brands aggregate/normalise Customer data (e.g.", keywords: ["personalisation","triggered","campaigns?","retail"], status: "published", bodyMd: "Brands aggregate/normalise Customer data (e.g. using CDPs) and invest in Decisioning solutions (Business Rules, ML or AI). The next step is to Activate that data across all touchpoints, including Physical Retail - this is where 'Triggered Campaigns' step in. 'Triggered Campaigns' is a repository of Campaigns/Experiences/Offers matched against Customer/Decisioning Data in Real-Time. As client data platforms are connected, Brands ensure Decisions are based on supported 'Triggered Campaigns' on that touchpoint. Initial focus is Physical Retail (hardest channel to support in real-time); intention to extend to all touchpoints. Triggered Campaigns also support Engaging and Interactive Retail experiences without any external data (so Brands can demonstrate value before integrating CDP/Decisioning solutions). Covered in more detail in the 'Personalisation' section." },
  { id: "faq-art-51000359234", categoryId: "faq-cat-digital-signage", order: 15, title: "PERSONALISATION | Update Campaign Interaction Settings", slug: "personalisation-update-campaign-interaction-settings", summary: "You can control how long the Pop-Up Message is shown for, and how long the Triggered Campaign plays back for, within the Campaign Interaction Setting section.", keywords: ["personalisation","campaign","interaction","settings","retail"], status: "published", bodyMd: "You can control how long the Pop-Up Message is shown for, and how long the Triggered Campaign plays back for, within the Campaign Interaction Setting section. Steps to update the Default Settings provided." },
  { id: "faq-art-51000359275", categoryId: "faq-cat-digital-signage", order: 16, title: "PERSONALISATION | Enabling QR Control & Updating the Default QR Code Settings", slug: "personalisation-enabling-qr-control-updating-the-default-qr-code-settings", summary: "Once you have created your first Triggered Campaign, enable QR Control.", keywords: ["personalisation","enabling","control","default","code","settings"], status: "published", bodyMd: "Once you have created your first Triggered Campaign, enable QR Control. QR Control shows a Unique QR Code on every connected Display. When a Visitor scans the QR Code they are presented with all the Active Triggered Campaigns running on that specific Display; selecting one starts it playing on the Display. Steps cover activating QR Control and defining the Default QR Code Settings used by all Landscape & Portrait Displays." },
  { id: "faq-art-51000359276", categoryId: "faq-cat-digital-signage", order: 17, title: "PERSONALISATION | Control QR Code Size|Colour|Position on an Individual Display", slug: "personalisation-control-qr-code-size-colour-position-on-an-individual-display", summary: "To override the Default QR Code settings for an individual Display, follow the steps to define Unique QR Code Settings on that Display.", keywords: ["personalisation","control","code","size","colour","position"], status: "published", bodyMd: "To override the Default QR Code settings for an individual Display, follow the steps to define Unique QR Code Settings on that Display." },
  { id: "faq-art-51000359277", categoryId: "faq-cat-digital-signage", order: 18, title: "PERSONALISATION | Allow Retail Staff to Activate Triggered Campaigns", slug: "personalisation-allow-retail-staff-to-activate-triggered-campaigns", summary: "If you Enable a Triggered Campaign on your Staff Tablet, Retail Staff can Trigger the Playback of these Campaigns on the individual Displays in their store themselves - useful…", keywords: ["personalisation","allow","retail","staff","activate","triggered"], status: "published", bodyMd: "If you Enable a Triggered Campaign on your Staff Tablet, Retail Staff can Trigger the Playback of these Campaigns on the individual Displays in their store themselves - useful to provide better Context or supporting Sales Promos during a conversation with a Store Visitor." },
  { id: "faq-art-51000359319", categoryId: "faq-cat-digital-signage", order: 19, title: "PERSONALISATION | Integrate Triggered Campaign with AI Agent Interaction", slug: "personalisation-integrate-triggered-campaign-with-ai-agent-interaction", summary: "NOTE: Requires your AI Agent to be Integrated with the Personalisation Hub Platform (contact the team).", keywords: ["personalisation","integrate","triggered","campaign","agent","interaction"], status: "published", bodyMd: "NOTE: Requires your AI Agent to be Integrated with the Personalisation Hub Platform (contact the team). Once a Triggered Campaign is created, you can activate it on any Retail Display based on the Conversational Intent of a Visitor. The Synonyms provided in the Triggered Campaign are matched to a Visitor's Utterances/Conversations; on a match, the appropriate Triggered Campaign plays on the respective Display. Steps to enable this on an individual Display provided." },
  { id: "faq-art-51000361014", categoryId: "faq-cat-digital-signage", order: 20, title: "PERSONALISATION | Trigger Campaign(s) based on Customer/Decisioning Data", slug: "personalisation-trigger-campaign-s-based-on-customer-decisioning-data", summary: "To leverage customer/decisioning data in retail requires your selected customer/decisioning vendor to provide an API to retrieve customer/decisioning data for the store visitor.", keywords: ["personalisation","trigger","campaign","based","customer","decisioning"], status: "published", bodyMd: "To leverage customer/decisioning data in retail requires your selected customer/decisioning vendor to provide an API to retrieve customer/decisioning data for the store visitor. Key questions: 1. Identifier required to retrieve Customer Data from the API - the Platform supports a variety of mechanisms (Store-Queueing, QR-Control, Appointments) to identify customers; typically clients use a hashed-email-address or hashed-mobile-number as the Identifier to securely retrieve Customer Data from their CDP Platform's API. 2. What Customer Data/Insights to leverage/surface in Retail (Product Holdings, Purchase History, Purchase Intent) - used to personalise a customer's experience and surfaced to Retail Staff when they pick customers up from the Queue. Raise a ticket for support connecting Customer/Decisioning Data." },
  { id: "faq-art-51000361015", categoryId: "faq-cat-digital-signage", order: 21, title: "PERSONALISATION | Use Customer / Decisioning Data to Personalise Retail", slug: "personalisation-use-customer-decisioning-data-to-personalise-retail", summary: "Steps to set up an internal POC/Demo of Personalisation in Retail - demonstrating the value of integrating Customer/Decisioning Data via the Platform's 'Visitor API'.", keywords: ["personalisation","customer","decisioning","data","personalise","retail"], status: "published", bodyMd: "Steps to set up an internal POC/Demo of Personalisation in Retail - demonstrating the value of integrating Customer/Decisioning Data via the Platform's 'Visitor API'. Connected data can be surfaced to Store Staff when picking customers up from the Queue. Requirements: Platform REST API Key (to authenticate with the Visitor API); Mobile Phone with a REST API Client App; Test Store/Display running Test Campaigns; Demo Use Cases. STEP 1: Create a REST API Key. STEP 2: Download a REST API Client App (e.g. 'REST Api Client Android'). STEP 3: If behind IP-Restrictions and the Demo phone isn't on a White-Listed network, white-list the demo IP. STEP 4: Define the Demo Use Cases and {Data} used to Trigger Personalised Campaigns. STEP 5: Validate Customer/Decisioning Data is received on a Connected Display. REST API settings: Method POST; URL [link]; Headers Content-Type=application/json, apikey=<created key>; Body raw JSON. USE CASE 1 'TRIGGER CAMPAIGN' on a specific display (fields include device_id, device_type, events, first_name, page_view, product_holdings[], source=APP, uuid={ACTUAL-STORE-CODE}, uuid_type=STORE_CODE, display_id={ACTUAL-DISPLAY-ID}). USE CASE 2 'TRIGGER CAMPAIGNS' on all displays in a specific store at once (same minus display_id). To stop Campaign Playback, resend with blank values. Notes: device_id any non-blank value; source = \"APP\" or \"STORE_TABLET\"; uuid = actual Store Code; uuid_type must be \"STORE_CODE\"; display_id = actual Display ID (from HQ Admin display details URL). Other supported Customer/Decisioning fields: Age, Gender, Product Type, Plan Type, Plan Value, Purchase History, Platform Data & Visitor Segments." },
  { id: "faq-art-51000361042", categoryId: "faq-cat-digital-signage", order: 22, title: "PERSONALISATION | Connect Your Mobile App or 3rd Party Site/API to the Visitor API", slug: "personalisation-connect-your-mobile-app-or-3rd-party-site-api-to-the-visitor-api", summary: "Follows on from the previous article on testing/leveraging the Platform's Visitor API.", keywords: ["personalisation","connect","mobile","party","site","visitor"], status: "published", bodyMd: "Follows on from the previous article on testing/leveraging the Platform's Visitor API. You can seamlessly connect other authorised Mobile-Apps/Sites to the Platform's Visitor API. As covered in the Store Mobile Sites section, the Platform allows Clients to create Localised Mobile Sites for each store that update based on Visitor/Customer context; Admin users can append Tokens onto the Mobile Site URLs. When a Visitor scans the QR-Code (via QR-Control) on any Connected Display, the Store Code & Display ID for that Display can be shared with your Mobile App (or a 3rd Party Site/API) using Tokens." },
];

async function createIfMissing(ref, data) {
  try {
    await ref.create(data);
    return "created";
  } catch (err) {
    if (err.code === 6 /* ALREADY_EXISTS */) return "skipped";
    throw err;
  }
}

async function main() {
  const catCounts = { created: 0, skipped: 0 };
  for (const c of categories) {
    const { id, ...rest } = c;
    const result = await createIfMissing(db.collection("faqCategories").doc(id), {
      ...rest, createdAt: now, updatedAt: now,
    });
    catCounts[result]++;
  }
  console.log(`FAQ categories: ${catCounts.created} created, ${catCounts.skipped} already present (skipped)`);

  const artCounts = { created: 0, skipped: 0 };
  for (const a of articles) {
    const { id, ...rest } = a;
    const result = await createIfMissing(db.collection("faqArticles").doc(id), {
      ...rest, projectId: null, needsReview: false,
      createdAt: now, updatedAt: now,
      ...(a.status === "published" ? { publishedAt: now } : {}),
    });
    artCounts[result]++;
  }
  console.log(`FAQ articles: ${artCounts.created} created, ${artCounts.skipped} already present (skipped)`);
}

main().catch((err) => {
  console.error("FAQ seed failed:", err);
  process.exit(1);
});
